-- Espumosos · Cavas · Champagne
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('COSSETANIA Brut Nature Organic', 'vino', 'espumoso', 'Cava ecológico catalán, brut nature. Fresco y untuoso a la vez — perfecto como aperitivo. Excelente calidad/precio.', 'Castell d’Or', 'Cava Brut Nature', 'Catalunya', 'Macabeo, Xarel·lo
Parellada', 'Amarillo limón con reflejos dorados, burbuja fina.', 'Manzana madura, cítricos y un fondo a frutos secos.', 'Untuoso, fresco y seco; final con toque de pomelo.', 'Aspecto visual: Color limón suave con reflejos dorados.
Aromas: Manzana madura con pronunciadas notas cítricas.
Paladar:Pomelo chino, nueces de macadamia. Untuoso en boca
Maridajes:Ideal con un surtido de quesos, ensaladas o salmón ahumado.', ARRAY['Aperitivo','Pescado blanco','Mariscos','Quesos cremosos']::text[], '6-8 °C', 12.0, 6.0, 26.0, '{"potencia": 4, "acidez": 8, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 10, 'Cava Brut Nature ecológico, segunda fermentación en botella.', 'Castell d''Or es una unión de cooperativas vitivinícolas catalanas creada en 2002 que agrupa a productores históricos del Penedès y Conca de Barberà.', 'La gama "Organic" usa uvas certificadas ecológicas. Es uno de los Brut Nature ecológicos más asequibles del mercado.', 'https://castelldor.com/es/producto/cossetania-cava-brut-nature/');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('COSSETANIA Brut Rose Organic', 'vino', 'espumoso', 'Cava rosado ecológico 100% Trepat (uva autóctona). Frutal y elegante; ideal para aperitivo o quesos.', 'Castell d’Or', 'Cava Brut', 'Catalunya', 'Trepat', 'Salmón claro, corona de finas burbujas.', 'Geranio, pomelo y ciruela roja.', 'Naranja sanguina y melocotón confitado; redondo.', 'Aspecto visual: Salmón claro, con corona de finas burbujas.Aromas: Geranio, pomelo y ciruelas rojas. Paladar: Naranja sanguina, mermelada de melocotón. Redondo en boca.
Maridajes: Ideal para queso azul, roquefort y surtido de pates', ARRAY['Aperitivo','Pescado blanco','Mariscos','Quesos cremosos']::text[], '6-8 °C', 12.0, 6.0, 26.0, '{"potencia": 4, "acidez": 8, "taninos": 1, "dulzura": 2, "afrutado": 7}'::jsonb, NULL, true, false, 20, 'Cava Brut ecológico de uva Trepat.', 'Castell d''Or es una unión de cooperativas catalanas. La uva Trepat es autóctona de la Conca de Barberà y solo se usa para rosados.', 'La Trepat aporta este color salmón tan característico — una uva tinta de piel fina que se vinifica en rosado.', 'https://castelldor.com/es/producto/cossetania-cava-brut-rosat/');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('Roger Goulart Brut Nature', 'vino', 'espumoso', 'Cava reserva con larga crianza en cavas a 30 m bajo tierra. Mineral y persistente — para quien busca algo más serio que un cava normal.', 'Roger Goulart', 'Cava Brut', 'Catalunya', '40% xarel·lo
30% macabeo
30% parellada', 'Amarillo pálido con reflejos verdosos, burbuja fina y persistente.', 'Manzana verde, pera y cítricos sobre un fondo de bollería.', 'Seco y vivo, paso fresco; final mineral.', 'Elaboración de variedades por separado. Las uvas son refrigeradas previamente al prensado (para evitar pérdida de aromas). Rendimientos de prensado de mosto del 50%. Desfangado estático a baja temperatura. Fermentación de los mostos a 16-18ºC con levadura seleccionada. Vinos bases con un componente ácido importante y un pH bastante bajo para poder realizar una crianza larga. Tras el tiraje, se realiza la segunda fermentación y crianza en cavas situadas a 30 metros de profundidad, a una temperatura constante todo el año de 14ºC.', ARRAY['Aperitivo','Pescado blanco','Mariscos','Quesos cremosos']::text[], '6-8 °C', 12.0, 6.0, 30.0, '{"potencia": 4, "acidez": 8, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, '[{"critico": "Peñín", "nota": "89"}]'::jsonb, true, false, 30, 'Larga crianza en cavas a 30 m de profundidad, temperatura constante 14 °C.', 'Roger Goulart se fundó en 1882 en Sant Esteve Sesrovires (Penedès). Familia centenaria del cava.', 'Sus cavas subterráneas a 30 m de profundidad mantienen 14 °C todo el año — condiciones perfectas para crianzas largas.', 'https://www.rogergoulart.com/cavas/roger-goulart-brut-nature-reserva/');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('Roger Goulart Brut rose', 'vino', 'espumoso', 'Cava rosado con coupage poco habitual (Garnacha-Monastrell-Pinot Noir). Frutal y festivo.', 'Roger Goulart', 'Cava Brut', 'Catalunya', '90% garnacha
5% monastrell
5% pinot noir', 'Rosa frambuesa brillante, burbuja fina.', 'Frutos rojos frescos (fresa, frambuesa) y toque floral.', 'Fresco, frutal y equilibrado; final ligero.', 'Elaboración de variedades por separado. Maceración pelicular a baja temperatura. Rendimiento de prensado del 50%. Fermentación de los mostos a 16-18ºC con levadura seleccionada. Vinos bases con una componente ácida importante y un pH bastante bajo para garantizar unas crianzas largas. Tras el tiraje, se realiza la segunda fermentación y crianza en cavas situadas a 30 metros de profundidad, a una temperatura constante todo el año de 14ºC.', ARRAY['Aperitivo','Pescado blanco','Mariscos','Quesos cremosos']::text[], '6-8 °C', 12.0, 6.0, 30.0, '{"potencia": 4, "acidez": 8, "taninos": 1, "dulzura": 2, "afrutado": 7}'::jsonb, NULL, true, false, 40, 'Maceración pelicular a baja temperatura; segunda fermentación a 14 °C.', 'Roger Goulart, fundada en 1882, es de las casas históricas del Penedès. Sus cavas están excavadas en piedra a 30 m bajo tierra.', 'Mezcla Garnacha, Monastrell y Pinot Noir — un coupage poco habitual que aporta complejidad.', 'https://www.rogergoulart.com/cavas/roger-goulart-brut-rose/');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('GRAMONAIII LUSTROS', 'vino', 'espumoso', 'Corpinnat con +7 años de crianza, estructurado y gastronómico — no un cava de aperitivo. Vino para acompañar comida seria.', 'Gramona', 'Corpinnat / Penedès', 'Catalunya', '41% xarel·lo,39% macabeo, 20% parellada', 'Dorado intenso, burbuja muy fina y elegante.', 'Frutos secos tostados, pan recién horneado y fruta confitada.', 'Cremoso, complejo y seco; final largo y mineral.', 'De color dorado, los aromas recuerdan a fruta blanca y flores de manzanilla. Las notas de crianza son muy evidentes y muestran brioche, miga de pan y orejones. Es un vino plenamente gastronómico, estructurado, con una frescura vibrante y una redondez llena de carácter', ARRAY['Aperitivo','Pescado blanco','Mariscos','Quesos cremosos']::text[], '8-10 °C', 12.0, NULL, 56.0, '{"potencia": 6, "acidez": 8, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 50, 'Más de 84 meses (7 años) sobre lías, 100 % artesanal.', 'Gramona, fundada en 1881 en Sant Sadurní, es referente mundial en cavas de larga crianza. Pertenece a Corpinnat (los productores que se separaron del Cava por exigir mayor calidad). Biodinámica.', '"III Lustros" significa 15 años — pero en realidad pasa más de 7 años en rima (sobre lías). Vino para abrir botellas grandes.', 'https://gramona.com/docs_web/gramona_IIIlustros_esp.pdf');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('TRADITION', 'vino', 'espumoso', 'Champagne de Ambonnay, pueblo Grand Cru de Pinot Noir. Cremoso y equilibrado — para quien aprecia champagne sin pedir Laurent-Perrier.', 'Curutier', 'Champagne', 'Francia', 'Pinot Noir, Chardonnay 30%', 'Amarillo dorado, burbuja fina y constante.', 'Pera, manzana al horno, brioche y un toque de nuez.', 'Cremoso, fresco y elegante; final cítrico largo.', 'Amarillo pajizo · Fruta blanca, cítricos, pan · Equilibrado · 8-10 °C para todos los gustos, amplio y a la vez fresco con una burbuja delicada y cremosa donde las notas de manzana y bollería se equlibran con el peso de Ambonnay.', ARRAY['Aperitivo','Pescado blanco','Mariscos','Quesos cremosos']::text[], '8-10 °C', 12.0, NULL, 85.0, '{"potencia": 4, "acidez": 8, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 60, 'Champagne con base de Pinot Noir y Chardonnay (Ambonnay Grand Cru).', 'Curutier es una pequeña casa familiar en Ambonnay, uno de los 17 Grand Cru de Champagne, especializada en Pinot Noir.', 'Ambonnay es zona Pinot Noir Grand Cru — solo 17 pueblos de Champagne tienen esta calificación máxima.', 'https://app.box.com/s/g03h6cm4e4q4k1ici56yjgnqsulpm96v');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('LAURENT-PERRIER La Cuvée Brut', 'vino', 'espumoso', 'Champagne icónico, casa fundada en 1812. Estilo fresco y elegante. La opción "segura" cuando alguien pide algo top.', 'Laurent-Perrier', 'Champagne', 'Francia', 'Pinot Noir, Chardonnay, Meunier', 'Amarillo pajizo con reflejos dorados, burbuja muy fina y persistente.', 'Cítricos, flor blanca, bollería y fruta de hueso.', 'Ligero, fino y delicado; gran frescura, final elegante.', 'Vista: Capa dorada pálida. Burbuja muy fina que alimenta un cordón de espuma muy persistente.Nariz:Delicado en nariz con aromas a cítricos frescos y flores blancas.
Boca: La complejidad del vino se expresa en notas sucesivas de melocotón de viña y frutos blancos. Equilibrio perfecto entre frescura y finura con sabores afrutados muy presentes al final de la degustación.', ARRAY['Aperitivo','Pescado blanco','Mariscos','Quesos cremosos']::text[], '8-10 °C', 12.0, NULL, 101.0, '{"potencia": 4, "acidez": 8, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 70, 'Mín. 4 años en bodega (mucho más que el mínimo legal de 15 meses).', 'Laurent-Perrier se fundó en 1812 en Tours-sur-Marne. Es una de las pocas grandes maisons que sigue siendo familiar (familia de Nonancourt).', 'Pionera del estilo "Ultra Brut" (sin azúcar añadido) en los años 80. La Cuvée es su buque insignia.', 'https://www.laurent-perrier.com/es/champagnes/la-cuvee/');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('KRIPTA', 'vino', 'espumoso', 'Cava Paraje Calificado — la calificación MÁXIMA de España. Botella ánfora inconfundible: una experiencia visual y gustativa.', 'Agustí Torelló Mata', 'Cava Paraje Calificado', 'Catalunya', 'Macabeo, Xarel·lo, Parellada', 'Dorado intenso, burbuja muy fina y aspecto sedoso.', 'Bollería, miel, frutos secos tostados y notas balsámicas.', 'Untuoso, complejo y mineral; final muy largo.', 'reflexos daurats, bombolla integrada amb rosari persistent. Marcades notes de fruita madura, brioixeria i torrats lleugers.', ARRAY['Aperitivo','Pescado blanco','Mariscos','Quesos cremosos']::text[], '8-10 °C', 12.0, NULL, 134.0, '{"potencia": 6, "acidez": 8, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 80, 'Brut Nature, ecológico, vendimia manual, certificación vegana.', 'Agustí Torelló Mata se fundó en 1955 en Sant Sadurní. KRIPTA es su vino icónico desde 1979 — uno de los primeros cavas de prestigio.', 'Botella inspirada en las ánforas griegas: no se sostiene de pie sola, hay que servirla en cubitera. Solo tiene Cava Paraje Calificado, la calificación más alta posible.', 'https://www.cellerkripta.com/producto/kripta');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('ARMAND DE BRIGNAC Brut', 'vino', 'espumoso', 'Botella de oro ("Ace of Spades"). Jay-Z compró la marca en 2014. Champagne de celebración por excelencia.', 'Armand de Brignac', 'Champagne AOC', 'Francia', 'Pinot Noir, Chardonnay, Pinot Meunier', 'Dorado intenso con burbuja muy fina.', 'Bollería, frutos secos, miel y fruta blanca confitada.', 'Cremosa, envolvente y elegante; final largo y persistente.', 'Botella dorada · Celebración · Único champagne premium del depósito', ARRAY['Aperitivo','Pescado blanco','Mariscos','Quesos cremosos']::text[], '8-10 °C', 12.0, NULL, 485.0, '{"potencia": 4, "acidez": 8, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 90, 'Champagne premium con larga crianza.', 'Lo elabora la familia Cattier (Champagne) desde 2006. En 2014 Jay-Z compró la marca. Es el "Ace of Spades" mundial.', '¡La botella es de oro! Cada una se decora a mano con etiquetas de peltre. Es el champagne de las celebraciones de la cultura hip-hop por excelencia. Edición limitada.', 'https://armanddebrignac.com');

-- Blancos · Mallorca
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('MOSAIC', 'vino', 'blanco mallorca', 'Línea propia de Catavinos con uvas mediterráneas. Fresco y aromático — el blanco "fácil" para abrir mesa.', 'BODEGAS ANGEL', 'VT Mallorca', 'Mallorca', 'Prensal, Viognier, Moscatel', 'Amarillo pajizo brillante con reflejos verdosos.', 'Fruta blanca y tropical con un toque floral mediterráneo.', 'Fresco, ligero y aromático; acidez vibrante.', NULL, ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '8-10 °C', 12.5, 4.0, 20.5, '{"potencia": 4, "acidez": 7, "taninos": 1, "dulzura": 2, "afrutado": 8}'::jsonb, NULL, true, false, 100, 'Joven en depósito de acero inoxidable.', 'MOSAIC es la línea propia de Catavinos, distribuidora histórica mallorquina. Se elabora en colaboración con bodegas locales.', 'Coupage de Prensal (la uva blanca más típica de Mallorca), Viognier y Moscatel — combina lo autóctono con dos variedades aromáticas.', 'https://catavinos.es');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('Son Caló', 'vino', 'blanco mallorca', '100% Prensal, la uva blanca autóctona de Mallorca. Alegre y muy mallorquín — perfecto para clientes que quieren probar lo de aquí.', 'Miquel Oliver', 'VT Mallorca', NULL, 'Prensal', 'Amarillo pálido con irisaciones verdosas, brillante.', 'Fruta fresca con fondos florales.', 'Sabroso, ligero y vivo; alegre y muy mallorquín.', 'De bonito color amarillo pálido con irisaciones verdosas. Gratos aromas de fruta fresca con fondos florales. En boca es sabroso, ligero y vivo. Buena constitución. Alegre y sugerente. Un vino muy mallorquín', ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '8-10 °C', 12.5, NULL, 21.5, '{"potencia": 4, "acidez": 7, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 110, 'Joven, en depósito.', 'Miquel Oliver es bodega de Petra (Pla i Llevant), pionera mallorquina desde 1912. Familia con seis generaciones de viticultores.', 'Prensal Blanc (también llamada Moll) es la uva blanca autóctona por excelencia de Mallorca. "Son Caló" hace referencia a una cala mallorquina.', 'https://miqueloliver.com/vinos/');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('CONNEXIÓ Prensal/Viognier', 'vino', 'blanco mallorca', 'Combina Prensal mallorquín con Viognier mediterráneo. Equilibrado y fresco — un blanco para todos.', 'Santa Catarina', 'VT Mallorca', 'Santa María del Camí (Raiguer)', 'Prensal, Viognier, Giró Ros', 'Amarillo pajizo limpio y brillante.', 'Fruta blanca, melocotón y un toque floral.', 'Equilibrado, fresco y con buena estructura aromática.', NULL, ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '8-10 °C', 12.5, 6.0, 22.5, '{"potencia": 4, "acidez": 7, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 120, 'Joven en depósito; algo de fermentación parcial.', 'Santa Catarina (Raiguer) elabora junto a Catavinos esta gama. Coupage entre la autóctona Prensal y la mediterránea Viognier.', 'Incorpora Giró Ros, otra uva mallorquina poco común — una "conexión" entre lo local y lo internacional, de ahí el nombre.', NULL);
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('Muscat', 'vino', 'blanco mallorca', '¡El primer Moscatel SECO de España! Aromático sin ser dulce. Perfecto para sushi y cocina asiática.', 'Miquel Oliver', 'VT Mallorca', NULL, 'Moscatel', 'Amarillo pálido con tonos verdosos, brillante.', 'Aromas varietales potentes y delicados de uva Moscatel.', 'Fresco, seco y muy expresivo; gran retronasal varietal.', 'Acaparador de premios en catas, este joven vino fue el primer moscatel seco de España en ser comercializado. Posee un atractivo color amarillo pálido con tonos verdosos. Brillante. Un vino muy fino, con potentes aromas varietales, aunque nada pesados (nariz delicada); fresco en boca, seco, equilibrado y muy suave, con gran expresión de aromas en boca (parece que se mastica uva Moscatel sana y bien madura). Difiere mucho del resto de los moscateles nacionales. Es uno de los vinos más originales elaborados en España', ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '8-10 °C', 12.5, NULL, 24.0, '{"potencia": 4, "acidez": 7, "taninos": 1, "dulzura": 2, "afrutado": 8}'::jsonb, NULL, true, false, 130, 'Joven; fermentación a baja temperatura.', 'Miquel Oliver, en Petra. Bodega histórica mallorquina con seis generaciones desde 1912.', '¡Fue el primer Moscatel SECO comercializado en España! Difiere por completo del resto de moscateles nacionales (que son dulces). Acaparador de premios.', 'https://miqueloliver.com/vinos/');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('CAN VIDELET Blanc de Blancs 2023', 'vino', 'blanco mallorca', 'Blanco mediterráneo de Andratx con 5 uvas distintas. Ligero y elegante — refresco mediterráneo puro.', 'Can Videlet', 'VT Mallorca', 'Andratx (Tramuntana SO)', 'Prensal Blanc, Moscatel, Chardonnay, Giró Ros, Sauvignon Blanc', 'Amarillo pálido brillante.', 'Flores blancas, fruta de hueso y matices cítricos mediterráneos.', 'Ligero, sedoso y equilibrado; acidez refrescante.', 'fresco, ligero y muy aromático.Un vino blanco elegante elaborado a partir de uvas blancas seleccionadas, que expresa la frescura y la luminosidad del paisaje mallorquín.En nariz destacan flores blancas, fruta de hueso y delicadas notas cítricas, acompañadas de matices frescos que evocan la brisa del Mediterráneo. En boca es ligero, equilibrado y sedoso, con una acidez refrescante que aporta vivacidad y armonía. Perfecto para disfrutar como aperitivo, con pescados, arroces mediterráneos, mariscos o tapas ligeras.Un blanco fresco y expresivo que captura la luz, la brisa marina y el carácter mediterráneo de Mallorca en cada copa.', ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '8-10 °C', 12.5, NULL, 29.0, '{"potencia": 4, "acidez": 8, "taninos": 1, "dulzura": 2, "afrutado": 8}'::jsonb, NULL, true, false, 140, 'Joven; coupage de cinco variedades.', 'Can Videlet es una pequeña bodega de Andratx (Tramuntana SO). Proyecto familiar reciente que apuesta por viñedos en altura.', 'Mezcla 5 variedades: Prensal, Moscatel, Chardonnay, Giró Ros y Sauvignon Blanc — un Blanc de Blancs muy diverso para Mallorca.', 'https://www.canvidalet.com/es/products/blanc-de-blancs-2025?_pos=2&_psq=blanc&_ss=e&_v=1.0');

-- Blancos · Nacionales
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('Lb1 verdejo', 'vino', 'blanco nacional', 'Verdejo de Rueda con gran calidad/precio. Fresco con notas de hinojo. Vino seguro para acompañar.', 'Cuatro Rayas', 'Rueda', NULL, 'Verdejo', 'Amarillo pajizo con reflejos acerados, limpio y brillante.', 'Fresco y afrutado; hinojo y boj característicos.', 'Complejo y envolvente; paso fresco con buen volumen.', 'Elaborado con una selección de uvas de la variedad verdejo de viñedo propio. De color amarillo pajizo con reflejos acerados, brillante y de gran intensidad. Fresco y afrutado en nariz con un paladar complejo y envolvente con notas de hinojo y boj, típicos de la variedad. Ofrece a la vista un bonito color amarillo alimonado pálido, verdoso, limpio y brillante. MARIDAJE: Pescado y marisco fresco, pastas y arroces. 6/8ºC Fermentación en depósito de acero inoxidable Con removido de lías durante un mínimo de 3 meses.', ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '6-8 °C', 12.5, 4.0, 19.0, '{"potencia": 4, "acidez": 7, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 150, 'Fermentación en acero inoxidable; mín. 3 meses sobre lías.', 'Cuatro Rayas es la cooperativa más grande de Rueda, con más de 300 viticultores y desde 1935. Líder absoluto de la DO.', 'El nombre "Lb1" hace referencia al primer botellero ("línea botella 1") — su producto de entrada con calidad sólida.', NULL);
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('LE NATUREL ZERO (sin alcohol)', 'vino', 'blanco nacional', 'Vino SIN ALCOHOL real (no zumo). Ecológico, navarro. Para conductores, embarazadas, abstemios — sin sentir que pierden la experiencia.', 'AROA', 'Sin alcohol', 'Navarra', 'Garnacha Blanca y Viura', 'Amarillo pajizo limpio.', 'Fruta blanca y cítricos suaves.', 'Ligera y refrescante, sin alcohol; bien equilibrada.', NULL, ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '8-10 °C', 12.5, 4.0, 19.5, '{"potencia": 2, "acidez": 7, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 160, 'Vino base navarro desalcoholizado.', 'AROA es bodega navarra biodinámica. "Le Naturel" es su gama sin alcohol elaborada con tecnología de desalcoholización suave.', 'Es vino DE VERDAD desalcoholizado, no zumo de uva. Garnacha Blanca y Viura, mismo trato que un vino normal hasta la última fase.', NULL);
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('Laus', 'vino', 'blanco nacional', 'Coupage atípico Chardonnay-Garnacha de Somontano. Tropical y largo en boca. Para clientes que buscan algo distinto.', 'Laus', 'Somontano', 'Huesca', 'Chardonnay-Garnacha', 'Amarillo limón con destellos verdes y acerados.', 'Fruta tropical y cítrica con toque floral elegante.', 'Sabroso, potente y fresco; postgusto muy largo.', 'Vino blanco de aspecto luminoso, color amarillo limón con destellos verdes y acerados, propios de su juventud. En nariz presenta un complejo y elegante aroma frutal, con matices florales, destacando los cítricos y tropicales (corteza de limón, pera en almíbar, piña y plátano maduro). En boca es sabroso, potente y fresco. Destaca un postgusto muy largo y agradable que invita a beber. Perfecto para pescados, arroces, pastas o simplemente disfrutarlo al aire libre.', ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '8-10 °C', 12.5, 5.0, 20.0, '{"potencia": 4, "acidez": 7, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 170, 'Joven en depósito.', 'Bodegas Laus está en Barbastro (Huesca), DO Somontano. Forma parte del Grupo Damm desde hace años — por eso lo distribuye Damm.', 'Coupage poco habitual de Chardonnay y Garnacha Blanca — apostando por personalidad aragonesa más que por la pureza varietal.', 'https://www.bodegalaus.es/wp-content/uploads/2026/03/LAUS-Chardonnay-Garnacha-2025.pdf');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('IZADI Larrosa Garnacha Blanca', 'vino', 'blanco nacional', 'Garnacha Blanca de viñas viejas en Rioja (atípica). Ligera, mineral y muy fresca.', 'Izadi', 'Rioja', 'La Rioja', '100% Garnacha Blanca.', 'Amarillo brillante.', 'Fruta blanca y de hueso con notas florales y minerales.', 'Untuosa, ligera y cítrica; final con recuerdo mineral.', 'Amarillo pálido · Melocotón, hinojo, anís · Seco, ligero, cítrico · 8-10 °C Color amarillo brillante. Con aroma intenso a fruta blanca y de hueso, que se mezcla con notas florales. En boca es agradable y ligeramente untuoso, con una buena acidez final que le da profundidad y un notable recuerdo a fruta fresca y notas minerales.Selección de 12 has. de viñedos viejos de garnacha blanca plantados en vaso en torno al año 1960', ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '8-10 °C', 12.5, 5.0, 20.5, '{"potencia": 4, "acidez": 7, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 180, 'Selección de viñedos viejos plantados en vaso (~1960).', 'Izadi (de Artevino) es bodega de Villabuena, Rioja Alavesa, fundada en 1987. "Larrosa" es su línea más fresca.', 'Garnacha Blanca en Rioja es minoritaria — Izadi recupera esta uva con viñedos viejos plantados en vaso (sistema tradicional).', 'https://izadi.com/vinos-doca-rioja/larrosa-blanca');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('Pandora', 'vino', 'blanco nacional', 'Sauvignon Blanc en Rueda (raro). Lichi, mango y pera en nariz. Diferente al Verdejo dominante.', 'BODEGAS PANDORA', 'Rueda', 'Valladolid', 'Sauvignon Blanc', 'Amarillo pajizo con matices verdosos, limpio y brillante.', 'Pera de agua, mango y lichi.', 'Amplio y fresco con sabores tropicales (lichi, pomelo).', 'Disfrútalo acompañado de foié o quesos cremosos como el ricotta, brie, camembert o feta. Un buen maridaje también puede ser el cebiche.Crianza sobre lías
Vista: Color amarillo pajizo con matices verdosos. Muy limpio y brillante.Aroma: pera de agua, mango, lichi. Boca:  Su amplitud, su frescura, sus sabores tropicales, lichis, pomelo.', ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '6-8 °C', 12.5, NULL, 21.0, '{"potencia": 4, "acidez": 8, "taninos": 1, "dulzura": 2, "afrutado": 7}'::jsonb, NULL, true, false, 190, 'Crianza sobre lías.', 'Bodegas Pandora, en Valladolid (Rueda), apuesta por Sauvignon Blanc en una zona dominada por Verdejo.', 'Hace Sauvignon Blanc en Rueda — una excepción frente al Verdejo dominante. Buen ejemplo de cómo el Sauvignon se adapta a la zona.', 'https://bodegaspandora.com/wp-content/uploads/2023/05/Ficha-de-Cata-Pandora-Sauvignon-Lias.pdf');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('A Telleira', 'vino', 'blanco nacional', 'Godello del Ribeiro — la uva blanca gallega de moda. Mineral y untuosa a la vez. "Telleira" = horno de tejas tradicional.', 'Bodegas Campante.', 'Ribeiro', 'Galicia', 'Godello', 'Amarillo pajizo brillante.', 'Fruta blanca madura y matices florales sobre fondo de lías.', 'Equilibrada y untuosa; final fresco y sabroso.', 'Un vino para amenizar aperitivos de quesos semicurados, pescados y arroces melosos. Comidas caseras de carnes de aves a la brasa y al horno bien salpimentadas.Elaboración por fermentación controlada a temperaturas de entre 15ºC y 18ºC durante aproximadamente 15 días, en depósitos de acero inoxidable de 5.000 litros. Posteriormente, se mantiene en crianza sobre lías durante al menos 3 meses.', ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '8-10 °C', 12.5, NULL, 22.0, '{"potencia": 6, "acidez": 7, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 200, 'Fermentación a 15-18 °C en acero, 3 meses sobre lías.', 'Bodegas Campante (Ourense, Ribeiro) lleva más de 75 años elaborando vinos gallegos. Familia Campos.', 'Su nombre viene de la tradición gallega: "telleira" hace referencia a los antiguos hornos de tejas construidos con la tierra rojiza de la zona. Conecta con el carácter del vino: auténtico, mineral y profundamente ligado al territorio.', 'https://bodegasgrm.com/a-telleira/?splash18=69f05caf95d55');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('Tobelos Blanco', 'vino', 'blanco nacional', 'Viura+Sauvignon de Rioja. Aromático y amplio. Excelente con carnes blancas y pescado azul.', 'Tobelos', 'Rioja', 'Cantabria', '85% Viura y 15% Sauvignon Blanc.', 'Amarillo limón.', 'Alta intensidad: fruta tropical, floral, herbal y especiada.', 'Amplia, fresca y equilibrada; postgusto frutal y persistente.', 'Ideal para acompañar carnes blancas, verduras de temporada y pescado azul.Color: amarillo limón.Nariz: alta intensidad con aromas de fruta tropical, floral, herbal y notas especiadas.Boca: con amplio volumen, fresco y equilibrado. Postgusto frutal y persistente.Temperatura de servicio: entre 9ºC y 11ºC.', ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '9-11 °C', 12.5, NULL, 23.0, '{"potencia": 4, "acidez": 8, "taninos": 1, "dulzura": 2, "afrutado": 7}'::jsonb, NULL, true, false, 210, 'Fermentación parcial sobre lías.', 'Tobelos es bodega de Briñas (Rioja Alavesa), proyecto reciente con base en viñedos viejos.', 'Mayoritariamente Viura (la uva blanca clásica de Rioja) con un 15 % de Sauvignon Blanc para aportar más aroma.', 'https://www.tobelos.com/producto/tobelos-blanco/');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('JOSÉ PARIENTE Verdejo', 'vino', 'blanco nacional', 'Verdejo referencia nacional, defensor histórico de la uva en Rueda. Untuoso y elegante con amargor final característico.', 'José Pariente', 'Rueda', 'Castilla y León', 'Verdejo', 'Amarillo pajizo brillante con reflejos verdosos.', 'Frutas blancas y cítricas, hinojo y fondo balsámico anisado.', 'Untuosa y elegante; amargor final característico del verdejo.', 'En la fase visual se aprecia un color amarillo pajizo brillante, con reflejos verdosos.Elegante, fresco y complejo. Muestra un marcado tono afrutado, que abarca la gama de frutas blancas y cítricos. Asimismo, se aprecian aromas de hinojo, de monte bajo y un fondo anisado, balsámico. Todo ello sobre un recuerdo mineral. En boca aparecen de nuevo las notas de fruta fresca. Untuoso, goloso y elegante con un suave toque de amargor final, característico de la variedad verdejo y sostenido por una buena acidez. Posee una gran estructura que favorece su persistencia. Destaca el volumen en boca de esta añada. La retronasal es compleja e intensa.Es un vino indicado para aperitivos y para acompañar platos a base de pescado,marisco, pastas, arroces y carnes blancas. Marida con todo tipo de ahumados, quesos suaves y embutidos.', ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '8-10 °C', 12.5, NULL, 23.5, '{"potencia": 4, "acidez": 7, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 220, 'Joven; fermentación a baja temperatura.', 'José Pariente fue uno de los primeros viticultores en defender el Verdejo de Rueda. Hoy lleva la bodega su hija Victoria Pariente, referente nacional.', 'Vinifica solo Verdejo — defensora a muerte de la uva. Sus vinos son referencia para entender qué es un Verdejo de calidad.', 'https://josepariente.com/los-vinos/');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('SEÑORÍO DE RUBIOS Albariño', 'vino', 'blanco nacional', 'Albariño potente y untuoso de O Rosal (Rías Baixas). Para mariscos y sushi premium.', 'Señorío de Rubios', 'Rías Baixas', 'Galicia', 'Albariño', 'Amarillo pajizo con ribetes verdosos, claro y brillante.', 'Frutas de hueso (melocotón, albaricoque) con toque floral.', 'Potente y sedosa, untuosa con acidez bien integrada.', 'A la vista presenta un color amarillo pajizo con ribetes verdosos, es claro, brillante y limpio. En nariz tiene una intensidad alta, es muy frutal recordando a frutas de hueso como el melocotón y el albaricoque; también aparece un pequeño toque floral. En boca es un vino muy potente, pero también sedoso y glicérido, lo que le da una acidez muy bien integrada. Tiene una buena estructura y untuosidad.Aperitivos, canapés variados, sushi, lubina, dorada, concha cruda, pulpo - calamar, revueltos y tortillas, pescadito frito, paella de pescado, arroz estilo y ensaladas estilo thai, pescado a la brasa, verduras a la brasa, caldo de pollo, sopa de verduras.', ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '8-10 °C', 12.5, NULL, 24.0, '{"potencia": 6, "acidez": 7, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 230, 'Joven; fermentación controlada.', 'Señorío de Rubios está en O Rosal (subzona meridional de Rías Baixas), zona templada por la influencia atlántica del Miño.', 'O Rosal está justo en la frontera con Portugal — el río Miño separa Rías Baixas del Vinho Verde portugués.', 'https://birdievinos.com/es/blancos/748-senorio-de-rubios-100-albarino.html?srsltid=AfmBOopJd4ytM9boSdvRxJwwQkPDOUKL3iFAz2zZbTb1-vR1Wvxqv3Dt#description');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('Circe', 'vino', 'blanco nacional', 'Verdejo SEMISECO — raro en Rueda. Fácil de beber, perfecto para clientes que dicen "no me gusta el seco".', 'Avelino Vegas', 'Rueda', 'Castilla y León', 'Verdejo', 'Amarillo pajizo brillante, juvenil.', 'Kiwi, carambola y un toque herbal de hinojo.', 'Ágil y semiseca; acidez viva equilibrada con dulzor sutil.', 'Circe Verdejo 2025 es un vino blanco fresco y desenfadado que se abre con aromas de kiwi, carambola y un toque herbal de hinojo que invita a acercarse sin pensar demasiado. En boca se muestra ágil y semiseco, con una acidez viva bien equilibrada por un dulzor sutil que lo hace fácil y muy agradable. Tiene ese punto juguetón que funciona de maravilla en el aperitivo y se mueve con soltura junto a pescados y mariscos, aportando frescura y ligereza. Un verdejo directo, de esos que se disfrutan sin complicaciones.', ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '6-8 °C', 12.5, NULL, 27.5, '{"potencia": 4, "acidez": 7, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 240, 'Joven; certificado vegano.', 'Avelino Vegas es una bodega segoviana con tradición; Circe es su línea joven y moderna en Rueda.', 'Es semiseco — algo poco habitual en Rueda. El dulzor sutil lo hace muy comercial y fácil de beber.', 'https://www.decantalo.com/es/es/circe-verdejo.html?srsltid=AfmBOopyd23Akzr2RXQ3dvxK4ixffdHAh0yLT8mZqu7kfvkOFLNJmuZd');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('Terres Gauda', 'vino', 'blanco nacional', 'Albariño noble con Caiño y Loureiro (uvas casi olvidadas). Carnoso, aterciopelado y muy largo.', 'Terres Gauda', 'Rías Baixas', 'Galicia', '70% Albariño, 25% Caiño y 5% Loureiro.', 'Amarillo limón brillante.', 'Muy expresiva: melocotón, piña y mandarina con anís y toque salino.', 'Carnosa y aterciopelada con frescura constante; final muy largo.', 'complejo y profundo, pero sorprendentemente fácil de beber.
En nariz: Es muy expresivo. Destacan las frutas maduras como el melocotón, piña y mandarina, con un fondo muy elegante de anís y un toque salino.En boca: Es un vino carnoso y aterciopelado que llena la boca, pero mantiene una frescura constante que lo hace muy agradable. Tiene un final larguísimo. 10° C-12° C.
MARIDAJE Maravillosa combinación con mariscos: ostras, almejas y cangrejo. Disfrútelo también con la cocina asiática o con carnes blancas o arroces.', ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '10-12 °C', 12.5, NULL, 28.5, '{"potencia": 6, "acidez": 7, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 250, 'Crianza sobre lías; coupage parcial fermentado.', 'Terras Gauda es una de las grandes bodegas de O Rosal (Rías Baixas). Recupera variedades autóctonas casi olvidadas.', 'Mezcla Albariño (70%) con Caiño Blanco (25%) y Loureiro (5%) — recuperando uvas históricas de O Rosal. No es monovarietal de Albariño.', 'https://www.terrasgauda.com/es/terras_gauda/fichas_de_cata/Terras_Gauda_2025.pdf');

-- Blancos · Internacionales
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('DROUHIN Mâcon-Villages Chardonnay', 'vino', 'blanco internacional', 'Chardonnay borgoñón clásico de Maison Drouhin (1880). Mineral y elegante — Borgoña accesible.', 'Joseph Drouhin', 'Bourgogne', 'Francia', 'Chardonnay', 'Amarillo dorado con reflejos verdosos.', 'Fruta blanca, flor blanca y un fondo mineral típico borgoñón.', 'Fresco, equilibrado y elegante; final mineral.', 'Amarillo pajizo · Fruta blanca, pera, flor · Fresco, redondo · 10-12 °C cualidades de frescura y madurez de la añada. En nariz, se distingue ralladura de limón confitado, flores blancas y un toque de miel y vainilla. En boca, el vino es de potencia media, con una textura rica y opulenta. El vino es redondo, con un gran equilibrio y un final puro y largo', ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '10-12 °C', 12.5, NULL, 33.0, '{"potencia": 4, "acidez": 7, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 260, 'Vinificación en frío; sin barrica notable.', 'Maison Joseph Drouhin se fundó en Beaune en 1880. Una de las grandes casas familiares de Borgoña, con bodegas históricas en el centro de Beaune.', 'Mâcon-Villages es la entrada al Chardonnay borgoñón — la zona del sur de la Côte Chalonnaise, terreno calcáreo igual que en los Grand Cru.', 'https://www.drouhin.com/fr_FR/vin/domaine-drouhin-oregon-chardonnay-arthur/2020');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('NIEPOORT Conciso Branco', 'vino', 'blanco internacional', 'Blanco del Douro por Dirk Niepoort, figura de culto. Mineral y salino — algo distinto y sofisticado.', 'Niepoort', 'Douro', 'Portugal', 'Bical, Malvasía, Encruzado', 'Amarillo pajizo con destellos verdosos.', 'Fruta blanca, cítricos, hierba fresca y mineralidad.', 'Fresco, vibrante y mineral; final salino y persistente.', 'Vista :Amarillo pajizo / Reflejos alimonados. Nariz: Aromas florales / Notas minerales / Notas de crianza / Maderas nobles / Hierbas balsámicas / Miel. Boca: Buena entrada / Acidez equilibrada / Con cuerpo / Ligeramente untuoso / Final agradable / Largo / Refrescante / Persistente
Consumo y conservación Servir entre 7 ºC y 10 ºC. Maridajes: Ensaladas / Arroces de pescado / Pescado blanco / Quesos cremosos', ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '7-10 °C', 12.5, NULL, 38.0, '{"potencia": 4, "acidez": 7, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 270, 'Fermentación parcial en barrica; crianza en madera noble.', 'Niepoort es una histórica casa portuguesa fundada en 1842. Hoy la lleva Dirk Niepoort, figura de culto que reinventó el Douro más allá del Oporto.', 'Coupage de uvas blancas autóctonas del Douro (Bical, Malvasía, Encruzado) — variedades tradicionalmente para Oporto blanco que aquí se vinifican como vino seco.', 'https://www.bodeboca.com/vino/niepoort-conciso-branco-2022');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('TE MATA Cape Crest Sauv. Blanc', 'vino', 'blanco internacional', 'Sauvignon Blanc de Hawke''s Bay (NZ) — bodega histórica de 1854. Más untuoso y menos verde que un Marlborough.', 'Te Mata', 'Hawke''s Bay', 'Nueva Zelanda', 'Sauvignon Blanc', 'Amarillo pajizo brillante.', 'Aromática: maracuyá, cítricos y herbáceos típicos.', 'Vibrante y compleja, acidez muy fresca; final largo.', 'Amarillo pálido · Pomelo, maracuyá, hierba · Vibrante, muy aromático · 8-10 °C. Carnes blancas, Legumbres, Ensaladas, Pescado blanco, Arroces', ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '8-10 °C', 12.5, NULL, 44.0, '{"potencia": 4, "acidez": 8, "taninos": 1, "dulzura": 2, "afrutado": 7}'::jsonb, NULL, true, false, 280, 'Fermentación parcial en barrica francesa.', 'Te Mata es una de las TRES bodegas más antiguas de Nueva Zelanda. Sus orígenes datan de 1854, cuando los Cambers — familia de inmigrantes ingleses — descubrieron las cualidades vitivinícolas del valle de Hawke.', 'Hawke''s Bay no es Marlborough — es la zona "más mediterránea" de NZ, con clima cálido. Sus Sauvignon son más untuosos y menos verdes que los típicos Marlborough.', 'https://www.decantalo.com/es/es/te-mata-cape-crest-sauvignon-blanc.html?srsltid=AfmBOoqrGU_xYViSz0Kz4Ijk-RtQFSg84stqiMIAxe5TD0a4O_mOf7UV');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('WILLIAM FÈVRE Chablis Les Clos Grand Cru 2020', 'vino', 'blanco internacional', 'El Grand Cru MÁS prestigioso de Chablis. Mineral, salino — literalmente sabe a ostra. Para pescados nobles y sake premium.', 'William Fèvre', 'Chablis Grand Cru AOC', 'Borgoña (Francia)', 'Chardonnay', 'Amarillo dorado brillante.', 'Cítricos, fruta blanca, ostra y mineralidad pura.', 'Tensa, mineral y muy elegante; final salino e infinito.', 'El Grand Cru más buscado de Chablis · Maridaje pescado/marisco/sake premium', ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '12-14 °C', 12.5, NULL, 250.0, '{"potencia": 4, "acidez": 9, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 290, 'Fermentación parcial en barrica; gran guarda.', 'William Fèvre es referencia absoluta de Chablis — fundó su dominio en 1959. Es propietario del mayor patrimonio en Grand Crus de toda la AOC.', '"Les Clos" es el Grand Cru MÁS grande y prestigioso de Chablis. Suelo Kimmeridgiense (lleno de fósiles marinos) — por eso el sabor a ostra se siente literalmente.', 'https://williamfevre.fr');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('ANTONIN GUYON Corton-Charlemagne Grand Cru 2022', 'vino', 'blanco internacional', 'Cima del Chardonnay mundial. Carlomagno mandó plantar uvas blancas para no manchar su barba — leyenda real.', 'Antonin Guyon', 'Corton-Charlemagne Grand Cru AOC', 'Borgoña (Francia)', 'Chardonnay', 'Dorado profundo con reflejos verdosos.', 'Fruta blanca, miel, brioche y mineral noble.', 'Amplia, untuosa y compleja; gran finura, final muy largo.', 'Cima del Chardonnay mundial · Maridaje top sake premium', ARRAY['Pescado blanco','Mariscos','Arroces','Quesos jóvenes']::text[], '12-14 °C', 12.5, NULL, 350.0, '{"potencia": 4, "acidez": 7, "taninos": 1, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 300, 'Fermentación y crianza en roble francés; gran guarda.', 'Antonin Guyon está en Savigny-lès-Beaune. Family Guyon, dueños de varios de los Grand Crus más prestigiosos de la Côte d''Or.', 'Corton-Charlemagne tiene leyenda real: el emperador Carlomagno mandó plantar uvas blancas en su colina porque el tinto le manchaba la barba blanca. Cima del Chardonnay mundial.', 'https://antoninguyon.com');

-- Rosados
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('Laus', 'vino', 'rosado', 'Coupage atípico Chardonnay-Garnacha de Somontano. Tropical y largo en boca. Para clientes que buscan algo distinto.', 'Laus', 'Somontano', 'Huesca', 'Garnacha-Syrah', 'Amarillo limón con destellos verdes y acerados.', 'Fruta tropical y cítrica con toque floral elegante.', 'Sabroso, potente y fresco; postgusto muy largo.', 'Vino blanco de aspecto luminoso, color amarillo limón con destellos verdes y acerados, propios de su juventud. En nariz presenta un complejo y elegante aroma frutal, con matices florales, destacando los cítricos y tropicales (corteza de limón, pera en almíbar, piña y plátano maduro). En boca es sabroso, potente y fresco. Destaca un postgusto muy largo y agradable que invita a beber. Perfecto para pescados, arroces, pastas o simplemente disfrutarlo al aire libre.', ARRAY['Aperitivo','Ensaladas','Pasta','Pescado azul']::text[], '8-10 °C', 12.5, 5.0, 20.0, '{"potencia": 4, "acidez": 6, "taninos": 2, "dulzura": 3, "afrutado": 7}'::jsonb, NULL, true, false, 310, 'Joven en depósito.', 'Bodegas Laus está en Barbastro (Huesca), DO Somontano. Forma parte del Grupo Damm desde hace años — por eso lo distribuye Damm.', 'Coupage poco habitual de Chardonnay y Garnacha Blanca — apostando por personalidad aragonesa más que por la pureza varietal.', 'https://www.bodegalaus.es/wp-content/uploads/2026/03/LAUS-Chardonnay-Garnacha-2025.pdf');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('MOSAIC', 'vino', 'rosado', 'Línea propia de Catavinos con uvas mediterráneas. Fresco y aromático — el blanco "fácil" para abrir mesa.', 'BODEGAS ANGEL', 'VT Mallorca', 'Mallorca', 'Prensal, Viognier, Moscatel', 'Rosa pálido brillante.', 'Frutos rojos frescos y notas florales mediterráneas.', 'Fresco, equilibrado y fácil de beber.', NULL, ARRAY['Aperitivo','Ensaladas','Pasta','Pescado azul']::text[], '8-10 °C', 12.5, 5.0, 20.5, '{"potencia": 4, "acidez": 6, "taninos": 2, "dulzura": 3, "afrutado": 7}'::jsonb, NULL, true, false, 320, 'Joven en depósito de acero inoxidable.', 'MOSAIC es la línea propia de Catavinos, distribuidora histórica mallorquina. Se elabora en colaboración con bodegas locales.', 'Coupage de Prensal (la uva blanca más típica de Mallorca), Viognier y Moscatel — combina lo autóctono con dos variedades aromáticas.', 'https://catavinos.es');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('IZADI Larrosa Rosé', 'vino', 'rosado', 'Rosado de Garnacha de Rioja, intenso y elegante con final eterno. Para acompañar comida, no solo aperitivo.', 'Izadi', 'Rioja', 'La Rioja', 'Garnacha', 'Rosa palo con ribete violeta.', 'Fresa, frambuesa y cereza con flor blanca y fruta de hueso.', 'Intensa y agradable; sutil, persistente, con acidez fina.', 'Vendimia manual. Fermentación en depósito de acero inoxdable.
Notas de cata:Color rosa palo con ribete violeta. Aroma intenso a fruta roja; fresa, frambuesa, cereza; también flores blancas y recuerdos de fruta de hueso como melocotón y albaricoque. Paso en boca intenso y agradable, con recuerdos a fruta fresca y notas florales. Sutil y persistente, con buena acidez y final eterno.', ARRAY['Aperitivo','Ensaladas','Pasta','Pescado azul']::text[], '8-10 °C', 12.5, NULL, 21.5, '{"potencia": 4, "acidez": 6, "taninos": 2, "dulzura": 3, "afrutado": 7}'::jsonb, NULL, true, false, 330, 'Vendimia manual; fermentación en acero.', 'Izadi (Artevino) en Villabuena de Álava (Rioja Alavesa) desde 1987.', '100 % Garnacha — la uva clásica para rosado en Rioja Oriental.', 'https://www.izadi.com/vinos-doca-rioja/larrosa-rose');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('Pago de cirus cuve rosado', 'vino', 'rosado', 'Rosado fermentado en barrica francesa — atípico. Más cuerpo que un rosado normal. 90 puntos en 3 guías.', 'Pago de cirus', 'Navarra', NULL, 'Tempranillo y Syrah', 'Rosa suave asalmonado.', 'Frutos rojos, flores blancas y un toque de roble francés.', 'Suave y ligera con buen cuerpo y acidez.', 'Rosado fermentado durante 3 meses en barricas de roble francés. Color rosa suave, asalmonado. Rosado fresco y afrutado, toques a frutas rojas y flores blancas. Suave y ligero en boca, mucho cuerpo en armonía con la acidez. D.O. Navarra.

Maridaje: Ideal como aperitivo y con pescados crudos, carpaccio de pescado blanco, pasta, salami o jamón ibérico de bellota, ensaladas, o mariscos.', ARRAY['Aperitivo','Ensaladas','Pasta','Pescado azul']::text[], '8-10 °C', 12.5, NULL, 23.0, '{"potencia": 4, "acidez": 6, "taninos": 2, "dulzura": 3, "afrutado": 7}'::jsonb, NULL, true, false, 340, '3 meses en barricas de roble francés.', 'Pago de Cirus está en Lerín (Navarra). Apuestan por rosados de gastronomía, fermentados en madera.', 'Fermentar el rosado en barrica es muy poco común — le da volumen y complejidad de un vino blanco con barrica. 90 puntos en Peñín, Suckling y Tim Atkin.', 'https://www.pagodecirsus.com/es/7_rose-gran-cuvee-especial.html');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('SINCRONIA Rosat', 'vino', 'rosado', 'Rosado mallorquín ECOLÓGICO biodinámico (Mesquida Mora). Sandía y nectarina — frescura pura.', 'Barbara Mesquida (Mesquida Mora)', 'VT Mallorca', 'Porreres (Pla i Llevant)', 'Callet, Merlot, Cabernet', 'Rosa fresa con destellos brillantes.', 'Sandía, nectarina y notas estivales.', 'Fresca, vibrante, viva y con buena acidez.', 'Prensado con raspón de las diferentes variedades, desfangado y fermentadas por separado según el momento de maduración. Aromas a fruta de verano, con notas muy marcadas de sandía y nectarina. En boca es fresco, vibrante, ácido y vivo.', ARRAY['Aperitivo','Ensaladas','Pasta','Pescado azul']::text[], '8-10 °C', 12.5, NULL, 27.0, '{"potencia": 4, "acidez": 6, "taninos": 2, "dulzura": 3, "afrutado": 7}'::jsonb, NULL, true, false, 350, 'Prensado con raspón; fermentaciones separadas por uva.', 'Mesquida Mora es proyecto familiar en Porreres (Pla i Llevant). Bárbara Mesquida elabora vinos biodinámicos con uvas autóctonas.', 'Biodinámica certificada. Mezcla la autóctona Callet con Merlot y Cabernet — el Callet aporta el carácter mallorquín al coupage.', 'https://mesquidamora.com/es/vino/sincronia-rosat/');

-- Tintos · Mallorca
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('MOSAIC', 'vino', 'tinto mallorca', 'Línea propia de Catavinos con uvas mediterráneas. Fresco y aromático — el blanco "fácil" para abrir mesa.', 'BODEGAS ANGEL', 'VT Mallorca', 'Mallorca', 'Manto Negro, Cabernet, Merlot, Syrah, Monastrell', 'Amarillo pajizo brillante con reflejos verdosos.', 'Fruta blanca y tropical con un toque floral mediterráneo.', 'Fresco, ligero y aromático; acidez vibrante.', NULL, ARRAY['Cordero','Quesos curados','Embutidos','Asados']::text[], '8-10 °C', 13.5, 5.0, 25.0, '{"potencia": 6, "acidez": 5, "taninos": 4, "dulzura": 2, "afrutado": 7}'::jsonb, NULL, true, false, 360, 'Joven en depósito de acero inoxidable.', 'MOSAIC es la línea propia de Catavinos, distribuidora histórica mallorquina. Se elabora en colaboración con bodegas locales.', 'Coupage de Prensal (la uva blanca más típica de Mallorca), Viognier y Moscatel — combina lo autóctono con dos variedades aromáticas.', 'https://catavinos.es');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('Son Caló', 'vino', 'tinto mallorca', '100% Prensal, la uva blanca autóctona de Mallorca. Alegre y muy mallorquín — perfecto para clientes que quieren probar lo de aquí.', 'Miquel Oliver', 'VT Mallorca', NULL, 'Callet', 'Cereza con intensos matices azulados.', 'Gran expresión aromática, fruta primaria y toque silvestre.', 'Carnoso, afrutado y largo; sabroso y fresco.', 'De bonito color amarillo pálido con irisaciones verdosas. Gratos aromas de fruta fresca con fondos florales. En boca es sabroso, ligero y vivo. Buena constitución. Alegre y sugerente. Un vino muy mallorquín', ARRAY['Cordero','Quesos curados','Embutidos','Asados']::text[], '8-10 °C', 13.5, 6.0, 27.0, '{"potencia": 6, "acidez": 5, "taninos": 4, "dulzura": 2, "afrutado": 7}'::jsonb, NULL, true, false, 370, 'Joven, en depósito.', 'Miquel Oliver es bodega de Petra (Pla i Llevant), pionera mallorquina desde 1912. Familia con seis generaciones de viticultores.', 'Prensal Blanc (también llamada Moll) es la uva blanca autóctona por excelencia de Mallorca. "Son Caló" hace referencia a una cala mallorquina.', 'https://miqueloliver.com/vinos/');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('SUARA', 'vino', 'tinto mallorca', 'Cabernet 100% en Mallorca (atípico). Ecológico, aterciopelado. Demuestra que el Cabernet también funciona en la isla.', 'Karretània', 'VT Mallorca', 'Consell', 'Cabernet Sauvignon', 'Cereza picota con ribete grisáceo, capa media.', 'Fruta roja madura, vegetal, anisado y toques animales.', 'Aterciopelado y elegante, equilibrado y amable.', 'Con una crianza de 6 meses en roble francés este tinto tiene aromas a fruta roja madura y notas animales. A medida que el vino se va abriendo gana matices y aromas. Muy agradable en boca.De capa media ligera con color cereza picota y ribete de tonos grisáceos. En boca es amable, elegante, con carácter aterciopelado, y equilibrado. Presenta notas de fruta roja madura, toques vegetales y de anís.', ARRAY['Cordero','Quesos curados','Embutidos','Asados']::text[], '14-16 °C', 13.5, NULL, 27.5, '{"potencia": 7, "acidez": 5, "taninos": 7, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 380, '6 meses en roble francés.', 'Karretània es pequeña bodega de Consell (Raiguer, Mallorca). Apuesta por viticultura ecológica y mínima intervención.', '100 % Cabernet Sauvignon en Mallorca — atípico (la mayoría apuesta por Manto Negro o Callet). Demuestra que el Cabernet también funciona en la isla.', 'https://www.terradevins.es/es/vino-tinto/612-suara-cabernet-2018-8437000845249.html');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('SUPERNOVA', 'vino', 'tinto mallorca', 'Manto Negro de viñas viejas (60 años). Sedoso y mineral, mínima intervención. Para quien aprecia lo natural.', 'Ca''n Verdura Viticultors', 'VT Mallorca', 'Binissalem', 'Manto Negro', 'Capa media-alta con reflejos vivos.', 'Fruta negra madura, hierbas mediterráneas y toque ahumado.', 'Sedoso, expresivo; final largo y persistente.', '8 meses en barricas de roble francés. intenso, expresivo y sincero. En nariz destacan por los aromas de fruta negra madura, notas forales con un fondo de hierbas mediterráneos y un toque ahumado. En boca es sedoso, con buen paso por boca y un final largo y persistente. Vino procedente de viñedos de 60 años distribuidos en pequeñas parcelas por toda la zona de producción de la DO Binissalem-Mallorca. Mínima intervención, para favorecer la competencia, viticultura respetuosa. Perfecto para maridar con Asados, Cerdo estofado o Pollo a la parrilla.', ARRAY['Cordero','Quesos curados','Embutidos','Asados']::text[], '14-16 °C', 13.5, NULL, 34.0, '{"potencia": 6, "acidez": 5, "taninos": 4, "dulzura": 2, "afrutado": 7}'::jsonb, NULL, true, false, 390, '8 meses en roble francés.', 'Ca''n Verdura Viticultors está en Binissalem — proyecto joven liderado por Tomeu Llabrés desde 2007. Mínima intervención, viticultura respetuosa.', '100 % Manto Negro de viñedos viejos (60 años) en pequeñas parcelas — la uva tinta mallorquina por excelencia, expresada en su mejor versión.', 'https://vinscanverdura.com/supernova/');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('CAN XANET Cadmo Gorgollassa', 'vino', 'tinto mallorca', 'Lleva GORGOLLASSA, uva mallorquina casi extinguida. Beberlo es probar historia. Mineral y tostado.', 'Can Xanet', 'VT Mallorca', 'Sencelles (Raiguer)', 'Gorgollassa, Manto Negro, Syrah', 'Cereza brillante con borde violáceo.', 'Hierbas de monte, fruta licorosa y tostado intenso.', 'Redondo, sabroso y mineral.', 'Cadmo tiene un color cereza brillante con el borde violáceo, de aroma podemos encontrar hierbas de monte , fruta al licor y muy tostado (torrefactado). En boca redondo, sabroso y mineral', ARRAY['Cordero','Quesos curados','Embutidos','Asados']::text[], '14-16 °C', 13.5, NULL, 36.0, '{"potencia": 6, "acidez": 5, "taninos": 4, "dulzura": 2, "afrutado": 7}'::jsonb, NULL, true, false, 400, 'Crianza en madera; coupage de tres uvas.', 'Can Xanet es bodega de Sencelles (Raiguer). Pioneros en recuperar la Gorgollassa, una uva mallorquina casi extinguida.', '¡La Gorgollassa estuvo a punto de desaparecer! Es una uva tinta mallorquina rarísima, recuperada en los últimos años por unos pocos productores. Beberla es probar historia.', 'https://www.canxanet.com/cadmo-2018/');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('ÀNIMA NEGRA AN/2', 'vino', 'tinto mallorca', 'El AN/2 — la bodega que puso Mallorca en el mapa del vino fino. 92 PK. Equilibrado, jugoso, fácil.', 'Ànima Negra', 'VT Mallorca', 'Felanitx (Pla i Llevant)', 'Callet, Fogoneu, Manto Negro', 'Rojo guinda oscuro, capa media, limpio y brillante.', 'Compleja: fruta roja dulce, balsámicos, mineral y ahumado sutil.', 'Equilibrada y jugosa, terrosa con toque de pimienta; final largo.', 'Vista: Rojo guinda oscuro, limpio, brillante y de capa media. Nariz: Muy complejo y abierto. Destaca la fruta roja fresca y dulce (cerezas, fresas), acompañada de notas balsámicas, minerales (piedra seca) y un toque sutilmente ahumado y láctico. Boca: Equilibrado, jugoso y de trago fácil. Juega con un contraste entre un ligero dulzor y un suave amargor. Tiene cuerpo medio, buena acidez, fondo terroso y un toque a pimienta que lo hace muy refrescante. Final (Postgusto): Largo y muy satisfactorio, dejando recuerdos a tostados suaves y montebajo.', ARRAY['Cordero','Quesos curados','Embutidos','Asados']::text[], '15-17 °C', 13.5, NULL, 38.0, '{"potencia": 6, "acidez": 5, "taninos": 4, "dulzura": 2, "afrutado": 7}'::jsonb, '[{"critico": "Peñín", "nota": "92"}]'::jsonb, true, false, 410, 'Crianza media en roble francés. Cosecha 2021 con 92 puntos en Peñín.', 'Ànima Negra (Felanitx) se fundó en 1994 por Pep Ekker y se considera el proyecto que puso a Mallorca en el mapa del vino fino. Recuperaron la Callet como uva noble.', 'AN/2 es el vino "joven" de la casa, basado en Callet. El gran AN (etiqueta negra) es uno de los vinos icónicos de España. ¡La 2021 cosechó 92 PK!', 'https://www.vinissimus.com/es/vino/anima-negra-an-2/?srsltid=AfmBOorcykoMXF7HSd9vfwEb5GQa62Eu3KkNLiisYUhNQqXjFB3xu8NM');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('4 KILOS 12 Volts', 'vino', 'tinto mallorca', 'Tinto de Sergio Caballero (cofundador del Sónar) y Francesc Grimalt. Mínima intervención. Goloso y estructurado.', '4 Kilos Vinícola', 'VT Mallorca', 'Felanitx (Pla i Llevant)', 'Callet, Merlot, Syrah', 'Cereza brillante, capa media, buena lágrima.', 'Fruta muy madura, lácteos, vainilla y tostados suaves.', 'Goloso y estructurado; taninos y acidez muy bien compensados.', 'VISTA: Cereza brillante, capa media, buena lágrima NARIZ: Intensidad media, fruta muy madura, lácteos, vainillas, tostados muy suaves, junto a caramelos y algo de balsámicos BOCA:Goloso en boca, con buena estructura, acidez, grado y taninos muy bien compensados, al tanino le falta un poco de botella', ARRAY['Cordero','Quesos curados','Embutidos','Asados']::text[], '15-17 °C', 13.5, NULL, 40.5, '{"potencia": 6, "acidez": 5, "taninos": 4, "dulzura": 2, "afrutado": 7}'::jsonb, NULL, true, false, 420, 'Crianza en barrica; añada con un poco de evolución.', '4 Kilos Vinícola fue fundada en 2006 por Sergio Caballero (cofundador del festival Sónar) y Francesc Grimalt en Felanitx. Mínima intervención.', '"4 Kilos" venía del capital inicial: 4 millones de pesetas (4 "kilos"). "12 Volts" es su tinto más asequible — un homenaje al juego eléctrico del proyecto.', 'https://www.devinsmenorca.com/es/tienda-online/12-volts-2023/2540');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('TONI GELABERT Negre Selecció', 'vino', 'tinto mallorca', 'Pionero biodinámico de Mallorca desde los 80. Cero pesticidas. Tinto serio con crianza francesa.', 'Toni Gelabert', 'VT Mallorca', 'Manacor (Pla i Llevant)', 'Manto Negro, Cabernet', 'Cereza picota intenso.', 'Fruta negra madura, especiada, con elegante crianza.', 'Estructurado, taninos pulidos y final largo.', NULL, ARRAY['Cordero','Quesos curados','Embutidos','Asados']::text[], '15-17 °C', 13.5, NULL, 50.0, '{"potencia": 6, "acidez": 5, "taninos": 4, "dulzura": 2, "afrutado": 7}'::jsonb, NULL, true, false, 430, 'Crianza en barrica francesa.', 'Toni Gelabert es bodega de Manacor — pionera de la biodinámica en Mallorca, desde los años 80. Cero pesticidas.', 'Hizo lo de "vino sin sulfitos añadidos" cuando casi nadie lo hacía. La misma familia (Miquel, su hermano) elabora el Dolç des Port.', NULL);

-- Tintos · Nacionales
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('ONTAÑON CRIANZA', 'vino', 'tinto nacional', 'Crianza de Rioja Oriental con 92 puntos Suckling y Decanter. Frutal y jugoso — la opción segura para "un Rioja".', 'Ontañón', 'Rioja', 'Rioja Oriental', '90% tempranillo y 10% garnacha.', 'Rojo picota con reflejos rubí.', 'Frutos rojos frescos y maduros, vainilla, especias y cedro.', 'Cuerpo medio, taninos sedosos; final largo y elegante.', 'Marida con carnes, pasta, quesos curados e incluso platos de sabor intenso.criado en barrica mixta de roble americano y francés. Nariz: frutos rojos frescos y maduros (fresa, arándano, ciruela), toques florales, vainilla, especias y cedro. Boca: cuerpo medio, taninos sedosos, muy frutal y jugoso, con un final largo y elegante.', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '15-17 °C', 14.0, 5.0, 20.5, '{"potencia": 6, "acidez": 5, "taninos": 5, "dulzura": 2, "afrutado": 6}'::jsonb, '[{"critico": "James Suckling", "nota": "92"}]'::jsonb, true, false, 440, 'Crianza mixta en roble americano y francés. 92 puntos James Suckling y Decanter.', 'Bodegas Ontañón está en Logroño (Rioja Oriental). Familia Pérez Cuevas, que también elabora Queirón.', '90 % Tempranillo y 10 % Garnacha — perfil clásico de la Rioja Oriental, donde la Garnacha aporta cuerpo a la Tempranillo.', 'https://www.ontanon.es/los-vinos/coleccion-clasicos/ontanon-crianza/');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('FLOR DE VETUS', 'vino', 'tinto nacional', 'Tinta de Toro con 92 Parker. Cepas viejas pre-filoxéricas. Potente pero fresco.', 'Vetus', 'Toro', 'Castilla y León', 'crianza 9 meses                              Uvas de tinta de toro', 'Cereza picota profundo con ribete violáceo.', 'Fruta roja y negra madura, regaliz, especias y café tostado.', 'Potente y fresco, glicérico, taninos suaves; final largo.', 'Color cereza picota profundo con ribete violáceo. Intensidad media-alta en nariz en la que destaca la fruta roja y negra madura. Encontramos matices de regaliz, especias y lácteos, con un ligero fondo de caramelo de café y pan tostado. En boca es potente y fresco a la vez, cálido, glicérico y de taninos suaves. Final largo y fragante. 16 ºC y 17 ºC', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '16-17 °C', 14.0, NULL, 21.5, '{"potencia": 8, "acidez": 5, "taninos": 7, "dulzura": 2, "afrutado": 6}'::jsonb, '[{"critico": "Robert Parker", "nota": "92"}]'::jsonb, true, false, 450, '9 meses en barrica. Parker 92.', 'Bodegas Vetus está en Toro. La uva Tinta de Toro es una variante autóctona del Tempranillo, más concentrada y con piel gruesa.', 'En Toro, el Tempranillo se llama "Tinta de Toro" — cepas viejas que sobrevivieron a la filoxera (XIX) y mantienen la variedad pre-filoxérica.', 'https://www.bodegasvetus.com/vinos-do-toro/flor-de-vetus');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('IZADI Crianza', 'vino', 'tinto nacional', 'Rioja moderno con 90 Parker y 90 Peñín. Calidad/precio imbatible.', 'Izadi', 'Rioja', 'La Rioja', 'Tempranillo', 'Rojo picota.', 'Fruta negra, especia dulce y tostado.', 'Estructurado con taninos pulidos.', 'Rojo picota · Fruta negra, especia dulce, tostado · Estructurado, taninos pulidos · 15-17 °C', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '15-17 °C', 14.0, 5.0, 23.5, '{"potencia": 6, "acidez": 5, "taninos": 5, "dulzura": 2, "afrutado": 6}'::jsonb, '[{"critico": "Robert Parker", "nota": "90"}, {"critico": "Peñín", "nota": "90"}]'::jsonb, true, false, 460, 'Crianza en barrica. Parker 90, Peñín 90.', 'Izadi (Artevino) es bodega de Villabuena (Rioja Alavesa) desde 1987. Estilo "Rioja moderna" con uva Tempranillo de viñedos seleccionados.', 'La línea Crianza es su producto más popular — 90 puntos en Parker y Peñín por debajo de 15 € en bodega. Calidad/precio imbatible.', 'https://izadi.com/');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('Pruno', 'vino', 'tinto nacional', 'Ribera del Duero con 92 Parker, 91 Peñín. El Ribera "fácil" más reconocido — suave y goloso.', 'Bodega Finca Villacreces', 'Ribera del Duero', 'Valladolid', '95% Tempranillo; 5% Cabernet Sauvignon 12 meses barrica roble', 'Picota intenso.', 'Frutas rojas, regaliz, torrefactos y toffee.', 'Goloso, suave y agradable; entrada dulce.', 'Visual :Color picota intenso. Olfativa: Aroma a frutas rojas con un acompañamiento de role que hace prever su entrada golosa y dulce. Recuerda a fruta madura y regaliz con toques de torrefactos y toffe. Gustativa: Agradable paso por boca y suave recuerdo. Marida con:
Guisos de carne, embutidos curados, pescados, quesos de oveja, aves. 16º', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '16-17 °C', 14.0, NULL, 27.0, '{"potencia": 7, "acidez": 5, "taninos": 7, "dulzura": 2, "afrutado": 6}'::jsonb, '[{"critico": "Robert Parker", "nota": "92"}, {"critico": "Peñín", "nota": "92"}, {"critico": "Peñín", "nota": "91"}]'::jsonb, true, false, 470, '12 meses en barrica de roble. Parker 92, Peñín 91.', 'Bodega Finca Villacreces está en Quintanilla de Onésimo (Ribera del Duero). Pruno es su línea más asequible — gran calidad/precio.', '95 % Tempranillo y 5 % Cabernet Sauvignon — uno de los Ribera "fáciles" más reconocidos. Top en relación calidad-precio en su rango.', 'https://www.vinosribera.com/es/pruno-finca-villacreces.html');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('LUIS CAÑAS Crianza 2022', 'vino', 'tinto nacional', 'Bodega histórica (1928). Coupage Garnacha-Tempranillo (no solo Tempranillo). Envolvente y denso.', 'Bodegas Luis Cañas', 'Rioja', 'Rioja', 'Garnacha
Tempranillo', 'Rojo picota.', 'Frutal (fresa, plátano), vainilla, cedro y balsámicos.', 'Envolvente y densa con tanino potente pero redondo.', 'Color rojo picota. En nariz destaca su carácter frutal con notas de fresa y plátano, aparecen recuerdos, vainilla, madera de cedro, hojarasca, junto con notas balsámicas. En boca es envolvente y denso con tanino potente pero redondo.', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '15-17 °C', 14.0, NULL, 28.5, '{"potencia": 6, "acidez": 5, "taninos": 5, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 480, 'Crianza en barrica de roble.', 'Bodegas Luis Cañas está en Villabuena de Álava (Rioja Alavesa) desde 1928. Tres generaciones de viticultores.', 'Garnacha-Tempranillo (no solo Tempranillo) — Luis Cañas defiende mantener Garnacha en sus crianzas para más cuerpo.', 'https://vinosonline.es/es/vino-tinto/6680-luis-canas-crianza-2022-75-cl.html');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('LA PETITE AGNES', 'vino', 'tinto nacional', 'El Priorat "fácil" — para descubrir la zona sin gastar fortuna. Fresca y elegante.', 'Cal Grau', 'Priorat', 'Catalunya', '50% Garnacha y 50% Cariñena', 'Capa media con reflejos rubí.', 'Frutos rojos, hierbas aromáticas y tostados sutiles.', 'Fresca y equilibrada con acidez fina y delicada.', 'Elegante y aromático, con notas de frutos rojos, hierbas aromáticas y sutiles toques tostados. En boca, fresco y equilibrado, con una acidez perfecta y delicada concentración.Es un vino elegante y fácil de beber, con una maceración de 17 días con sus hollejos y una crianza de 4 meses mínimo en barrica francesa.', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '15-17 °C', 14.0, NULL, 29.5, '{"potencia": 6, "acidez": 5, "taninos": 5, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 490, 'Mín. 4 meses en barrica francesa; maceración 17 días con hollejos. 89 puntos James Suckling.', 'Cal Grau (Priorat) es un proyecto familiar de viticultura tradicional. "La Petite Agnès" es su Priorat más accesible, fácil de beber y elegante.', 'El nombre es homenaje a Agnés, una señora mayor que hace 40 años acostumbraba a pasear por la finca recogiendo hierbas aromáticas y medicinales.', 'https://www.vinosiberian.com/producto/la-petite-agnes-2023/');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('Tilenus pago florida crianza', 'vino', 'tinto nacional', 'Mencía del Bierzo con 91 Parker. Single vineyard. Untuosa y carnosa — la uva gallega que se ha puesto de moda.', 'Bodegas Estefania', 'DO Bierzo', NULL, 'Mencía', 'Rojo oscuro con reflejos ocre.', 'Fruta roja madura, madera francesa, especias y humo.', 'Untuosa y carnosa, taninos marcados; armoniosa y persistente.', 'ColorPotente vino de la variedad Mencía, precioso rojo oscuro con reflejos ocre.AROMA:En nariz gran finura, propia de la crianza, presenta aromas de frutas rojas maduras y finos de madera francesa, especias y humo.GUSTO:En boca presenta una amplia untuosidad y un tanino marcado procedente de la maceración y de la extracción en la barrica. El conjunto de sensaciones connota una gran armonía y equilibrio. Carnoso, dinámico, cálido y persistente.', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '15-17 °C', 14.0, NULL, 35.0, '{"potencia": 7, "acidez": 5, "taninos": 6, "dulzura": 2, "afrutado": 6}'::jsonb, '[{"critico": "Robert Parker", "nota": "91"}]'::jsonb, true, false, 500, '12 meses en barrica de roble francés. Parker 91.', 'Bodegas Estefania está en Dehesas (Bierzo). Pago Florida es viñedo singular — un "single vineyard" del Bierzo.', 'La Mencía es la uva del Bierzo y Galicia — durante años se subestimó, hoy es de las uvas españolas más respetadas. 91 Parker.', 'https://www.grauonline.es/vinos-tintos/tilenus-crianza.html');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('ELS PICS', 'vino', 'tinto nacional', 'Priorat con 15° invisibles en boca. 90 Parker. Densidad y mineral — para quien busca un Priorat serio.', 'Bodegas Mas Alta', 'Priorat', 'Catalunya', '50% Garnacha Tinta, 40% Cariñena, 5% Merlot, 5% Syrah', 'Cereza intenso.', 'Pastel de fresas y ciruelas cocidas, regaliz y mineral.', 'Cuerpo y densidad; equilibrio entre acidez, dulzor y amargor.', 'El vino brilla en copa con un intenso color cereza y despierta con aromas primarios y la calidez de un pastel de fresas y ciruelas cocidas al horno; arropadas por el frescor de una fina mineralidad, se distinguen notas de regaliz y de pólvora. Sus 15 grados de alcohol parecen desaparecer por arte de magia al servir el vino en copa. En boca tiene un gran cuerpo, densidad y potencia, y a medida que pasa tiempo en copa es más perfecto el equilibrio entre su buena acidez, un agradable dulzor y un ligero amargor de plantas aromáticas (tomillo) que persiste en el final.', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '16-17 °C', 14.0, NULL, 38.5, '{"potencia": 6, "acidez": 5, "taninos": 5, "dulzura": 2, "afrutado": 6}'::jsonb, '[{"critico": "Robert Parker", "nota": "90"}]'::jsonb, true, false, 510, 'Crianza en madera. Parker 90.', 'Bodegas Mas Alta está en La Vilella Alta (Priorat). Proyecto creado en 1999 por Christian Ducroux.', 'Tiene 15° de alcohol — alto pero invisible en boca. Es una característica del Priorat: alto grado pero gran equilibrio. Llicorella y vientos perfectos.', 'https://www.vinissimus.com/es/vino/els-pics/?srsltid=AfmBOor8syA2g4P054_lig7fcAX-CdSwZKnyvvaIqjOEENFuklgVfL-z');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('QUEIRON MI LUGAR 2018', 'vino', 'tinto nacional', 'Reserva Rioja exclusiva, 30 meses en madera, por gravedad. Pura seda con homenaje al poeta Bretón de los Herreros.', 'Dominio de Queirón (Familia Pérez Cuevas)', 'DOCa Rioja Oriental', 'Quel, Valle del Cidacos, Sierra de Yerga', '90% tempranillo y 10% garnacha.', 'Gran capa con irisaciones picotas y violáceas.', 'Fruta roja y negra madura, balsámicos, monte bajo y especias.', 'Potente, carnosa y elegante; pura seda con final largo.', 'Color: Gran capa de color, con irisaciones picotas y violáceas. Aroma: Fruta roja y fruta negra con un punto de madurez muy sensual. Destacan ciertas notas ahumadas, especias, minerales y madera, que tras la sensación de la fruta emociona por sus tonos balsámicos y aromáticos de monte bajo como romero y tomillo, así como sutiles recuerdos a regaliz. Sabor: En boca es potente, carnoso, elegante, muy equilibrado y sin ninguna arista. Es todo fluidez, con buena estructura,buena acidez y un final largo y persistente. Pura seda y elegancia.', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '16-17 °C', 14.0, NULL, 45.0, '{"potencia": 6, "acidez": 5, "taninos": 5, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 520, '18 meses en barrica (80 % francés / 20 % americano de primer uso) + 12 meses en tinas de madera. Elaboración íntegra por gravedad.', 'Dominio de Queirón (Familia Pérez Cuevas) elabora en Quel (Rioja Oriental). La misma familia que Ontañón. Elaboración 100 % por gravedad.', 'Su nombre es homenaje al poeta queleño Manuel Bretón de los Herreros, que en el siglo XIX escribió un romance titulado "Mi Lugar" describiendo el barrio de bodegas excavadas en la roca donde hoy trabaja la familia.', 'https://www.queiron.es/');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('EMILIO MORO 2023', 'vino', 'tinto nacional', 'Ribera referencia nacional. 95 Gourmets, 94 Wine Enthusiast. Sedoso y elegante — se vende solo.', 'Bodegas Emilio Moro', 'Ribera del Duero', 'Pesquera de Duero', 'Tempranillo', 'Picota intenso con reflejos violáceos, capa alta.', 'Frutos negros y rojos, vainilla, cacao y especias.', 'Sedosa y envolvente, tanino pulido; equilibrio y elegancia.', 'De color rojo picota intenso con reflejos violáceos que aún delatan su juventud, Emilio Moro 2023 presenta una capa alta y brillante. En nariz despliega una intensa expresión frutal, dominada por notas de frutos negros y rojos, que se entrelazan con matices de vainilla, cacao y un sutil toque especiado procedente de su crianza mixta en roble francés y americano. En boca se muestra sedoso y envolvente, con un tanino pulido que sostiene un equilibrio impecable entre madurez y frescura. La fruta vuelve a ser protagonista, arropada por una acidez precisa y una elegante integración de la madera. Su final es largo, armónico y persistente, dejando una sensación de agradable equilibrio.', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '16-17 °C', 14.0, NULL, 50.5, '{"potencia": 6, "acidez": 5, "taninos": 5, "dulzura": 2, "afrutado": 6}'::jsonb, '[{"critico": "Guía Gourmets", "nota": "95"}, {"critico": "Wine Enthusiast", "nota": "94"}]'::jsonb, true, false, 530, 'Crianza mixta en roble francés y americano. 95/100 Gourmets, 94/100 Wine Enthusiast.', 'Bodegas Emilio Moro está en Pesquera de Duero (Valladolid). Familia Moro con cuatro generaciones de viticultores. Tinto Fino de viñedos propios.', 'Tinto Fino es como llaman al Tempranillo en Ribera. Emilio Moro es referencia en la zona — el vino que más vende en restaurantes españoles según muchos rankings.', 'https://www.emiliomoro.com/producto/comprar-emilio-moro/?srsltid=AfmBOooDOgWcRz7I9caC9hVAXTl5-I-RpMgjLo1Ry5_P5nY6y-q4zcqA');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('PAGO DE LOS CAPELLANES', 'vino', 'tinto nacional', 'Ribera de gran altitud (850m). Familia Rodero-Villa. Suave entrada, final largo.', 'Pago de los Capellanes', 'Ribera del Duero', 'Castilla y León', 'Tinto Fino', 'Cereza con buena capa.', 'Fruta madura y negra, vainilla, regaliz y cuero.', 'Suave entrada, taninos finos; final largo y elegante.', 'Envejecimiento de 12 meses en barricas de roble francés de tostado medio. Posee un aroma muy franco, con un buen equilibrio fruta-madera en el que se funden los tonos de vainilla con fruta bien madura, frutos negros y de bosque.En boca sobresalen las notas de cuero y regaliz, con un paso suave, pero con taninos finos que proyectan final en boca y un postgusto largo y elegante', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '16-17 °C', 14.0, NULL, 57.5, '{"potencia": 6, "acidez": 5, "taninos": 5, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 540, '12 meses en barrica de roble francés (tostado medio).', 'Pago de los Capellanes está en Pedrosa de Duero (Burgos). Familia Rodero-Villa, viticultores históricos de Ribera con viñedos en altitud.', 'Tiene viñedos a más de 850 m de altitud — algo clave en Ribera del Duero. La altitud da gran amplitud térmica entre día y noche, perfecto para Tempranillo.', 'https://pagodeloscapellanes.com/vinos/parcela-el-picon/');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('VIÑA TONDONIA Reserva Tinto (2023)', 'vino', 'tinto nacional', 'López de Heredia (1877), Rioja ULTRA-clásico. Hacen TODO a la antigua: barricas a mano, claras de huevo. Una leyenda en copa.', 'López de Heredia', 'Rioja', 'La Rioja', 'Tempranillo, Garnacha, Graciano, Mazuelo', 'Rubí con reflejos anaranjados, capa media, limpio y brillante.', 'Fruta madura, vainilla y tostados; finura y complejidad envolvente.', 'Sedosa, especiada y compleja; vino de gran finura.', 'ColorLimpio y brillante. Color rubí con reflejos ligeramente anaranjados, muestra una intensidad de capa media. Muy agradable a la vista.AROMA:En nariz, se presenta con una finura y complejidad envolvente. Su frescura cautiva desde el primer contacto en la copa. Desprende suaves aromas de fruta madura y fruta fresca, que se conjuntan con una fusión maravillosamente agradable, notas sutilmente especiadas, donde las dulces como la vainilla y los tostados cogen la atención final. Una vez más tenemos delante, un vino de una finura indiscutible con una añada sensacional.GUSTO:Entrada en boca donde te acaricia el paladar, no es un vino complejo y con mucho cuerpo, eso sí, ofrece una preciosa experiencia para los sentidos: es un vino refinado, donde predomina la elegancia ante todo, con nervio y fresco, todo sensacionalmente casado con unos taninos integrados con una total consonancia perfecta', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '17-18 °C', 14.0, NULL, 65.0, '{"potencia": 6, "acidez": 5, "taninos": 5, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 550, 'Mín. 6 años en barrica de roble americano artesanal + tiempo en botella.', 'R. López de Heredia se fundó en Haro (Rioja) en 1877 — una de las bodegas más antiguas del mundo. Cuatro generaciones, siempre fieles a la tradición.', 'Hacen TODO a la antigua: barricas hechas a mano por su tonelero, claras de huevo para clarificar, etiquetas que parecen del siglo XIX. Su Tondonia es leyenda viva del clasicismo.', 'https://www.grauonline.es/vinos-tintos/vina-tondonia-negre-reserva.html');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('NIT DE NIN La Coma De''n Romeu 2018', 'vino', 'tinto nacional', 'Familia Pérez Nin-Ortiz, biodinámica. Vino de Finca singular. Producción limitadísima.', 'Familia Nin-Ortiz', 'DOQ Priorat', 'Catalunya', 'Cariñena (viñas viejas)', 'Picota intenso con reflejos rubí.', 'Mineral (llicorella), fruta negra, hierbas y mentol.', 'Profunda y elegante; mineral, cuerpo y frescura.', 'Familia Pérez · Vino de culto · Singularidad Priorat', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '16-17 °C', 14.0, NULL, 240.0, '{"potencia": 6, "acidez": 5, "taninos": 5, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 560, 'Crianza larga en barrica; viticultura biodinámica.', 'Familia Nin-Ortiz son matrimonio de viticultores biodinámicos en Priorat. Ester Nin y Carlos Ortiz — proyecto de culto desde los 90.', 'Vino de Finca: solo se elabora con uvas de un viñedo concreto ("Coma De''n Romeu"). Concentración y singularidad máxima del Priorat. Producción muy limitada.', 'https://familianinortiz.com');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('RIOJA ALTA 890 Gran Reserva 2010', 'vino', 'tinto nacional', 'Solo se elabora en cosechas excepcionales. Hacen sus propias barricas a mano. La 2010 es legendaria.', 'La Rioja Alta', 'DOCa Rioja', 'La Rioja', 'Tempranillo, Graciano, Mazuelo', 'Rubí con ribete teja, brillante.', 'Fruta confitada, cuero, tabaco, especias y madera noble.', 'Aterciopelada, compleja y muy larga; clásico atemporal.', 'Clásico por excelencia · Solo en cosechas excepcionales', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '17-18 °C', 14.0, NULL, 353.0, '{"potencia": 7, "acidez": 5, "taninos": 6, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 570, 'Mín. 6 años en bodega; barrica americana propia. Solo en cosechas excepcionales.', 'Bodegas La Rioja Alta se fundó en 1890 en Haro — la "estación enológica" de Rioja. Capítulo aparte: hacen sus propias barricas.', 'El "890" es número de homenaje al año de fundación (1890). Solo se elabora en cosechas excepcionales — la 2010 es legendaria.', 'https://riojalta.com');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('VEGA SICILIA Único Reserva Especial 2020', 'vino', 'tinto nacional', 'ÍCONO mundial del vino español. Bodega de 1864. "Reserva Especial" = coupage de varias añadas excepcionales.', 'Vega Sicilia', 'DO Ribera del Duero', 'Castilla y León', 'Tinto Fino, Cabernet Sauvignon', 'Granate profundo con reflejos teja.', 'Fruta confitada, especias, cuero, café y tabaco.', 'Aterciopelada, compleja y monumental; final muy persistente.', 'Coupage de cosechas · Imprescindible · Liga ícono', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '17-18 °C', 14.0, NULL, 817.0, '{"potencia": 7, "acidez": 5, "taninos": 7, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 580, 'Coupage de varias añadas (no es un vino de cosecha única).', 'Bodegas Vega Sicilia se fundó en 1864 por Eloy Lecanda — la primera bodega en plantar Cabernet en España. Familia Álvarez la compró en 1982 y elevó la marca al ícono mundial actual.', '"Reserva Especial" NO es una añada — es un coupage de tres cosechas seleccionadas. Único de los pocos vinos que mezcla vintages. Vega Sicilia es DEL MUNDO el vino español más reconocido.', 'https://vega-sicilia.com');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('L''ERMITA 2016', 'vino', 'tinto nacional', 'Álvaro Palacios, ~1.500 botellas/año. Viñedo en pendiente del 60 % trabajado a mano. De las botellas más codiciadas de España.', 'Álvaro Palacios', 'DOQ Priorat', 'Catalunya', 'Garnacha, Cariñena', 'Cereza intenso con destellos rubí.', 'Fruta negra concentrada, llicorella, especias y mineral noble.', 'Profunda, sedosa y muy compleja; final monumental y largo.', 'Uno de los vinos más codiciados de España · Liga ícono absoluto', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '17-18 °C', 14.0, NULL, 1476.0, '{"potencia": 6, "acidez": 5, "taninos": 5, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 590, 'Crianza larga en barrica francesa; viñedos centenarios.', 'Álvaro Palacios — descendiente de Palacios Remondo (Rioja) — llegó al Priorat con un grupo de jóvenes en los años 80 y revolucionó la zona. L''Ermita es el viñedo más singular: cepas viejísimas en pendiente extrema.', 'Producción minúscula (~1.500 botellas/año). Una de las botellas más codiciadas de España, junto a Vega Sicilia. Viñedo en pendiente del 60 % — todo trabajado a mano y caballo.', 'https://alvaropalacios.com');

-- Tintos · Internacionales
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('JABOULET Parallele 45 Rouge', 'vino', 'tinto internacional', 'Côtes du Rhône clásico, ecológico. Casa de 1834 (familia Frey). Garnacha-Syrah elegantes.', 'Domaines Paul Jaboulet Aîné', 'Côtes du Rhône AOC', 'Francia', '60% Garnacha / 40% Syrah', 'Granate oscuro y brillante.', 'Intensa y elegante, fruta roja con notas especiadas.', 'Estructurada con notas especiadas y de crianza.', 'Granate / Oscuro / Brillante.  Nariz:  Intensidad alta, Elegante, Fruta roja, Notas especiada.  Boca: Estructurado / Notas especiadas / Notas de crianza', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '15-17 °C', 14.0, NULL, 23.0, '{"potencia": 6, "acidez": 5, "taninos": 5, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 600, 'Crianza media; ecológico.', 'Domaines Paul Jaboulet Aîné es histórica casa del Ródano fundada en 1834. Desde 2006 propiedad de la familia Frey.', '"Parallèle 45" hace referencia al paralelo 45 (que pasa por la zona del Ródano norte). Es el coupage más vendido de Jaboulet — Garnacha y Syrah clásicos del Ródano sur.', 'https://www.vinissimus.com/es/vino/jaboulet-parallele-45-rouge/?srsltid=AfmBOopGQE0aoXt_sq0Pn0ZRG17U8BE_p9SKaUc3LmZkCX0Y1Mv6yWVt');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('PEREZ CRUZ', 'vino', 'tinto internacional', 'Cabernet del Maipo Andes (Chile) — la zona top. Estructurado, especiado, taninos robustos.', 'Vineyades', 'Valle del Maipo Andes', 'Chile', '92% Cabernet Sauvignon 8% Cabernet Franc', 'Rubí intenso y profundo, púrpura en ribete.', 'Casis, frutos negros maduros, cereza, especias y mentol.', 'Sólida y equilibrada, taninos robustos; final complejo y largo.', 'Color rubí intenso y profundo, con tonalidades púrpuras en el ribete. brillante y limpio. Aroma Notas clásicas de casis, de frutas negras maduras, cerezas, especias y elegantes matices de mentol. Boca Estructura sólida y equilibrada, con taninos robustos y persistentes. Rica complejidad y maravilloso final. Maridaje.estofados de carne, cordero asado, carrilleras de cerdo o ternera, ragú de ternera e incluso costillar. En cuanto a las guarniciones, debido a su cuerpo y taninos, marida bien con opciones robustas como puré de patatas, risotto de hongos, gratín de espinacas o incluso polenta con queso.', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '16-17 °C', 14.0, NULL, 26.5, '{"potencia": 7, "acidez": 5, "taninos": 7, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 610, '16-18 meses en barricas de roble francés (primer, segundo y tercer uso) + 10 % crianza en huevo.', 'Pérez Cruz está en el Valle del Maipo Andes, Chile. Familia Pérez Cruz con más de 100 años en la viticultura chilena.', '92 % Cabernet Sauvignon y 8 % Cabernet Franc — Maipo Andes es la zona de Cabernet por excelencia de Chile, comparable a Burdeos por su mineralidad.', 'https://cdn.shopify.com/s/files/1/0786/5961/7041/files/Ficha_Pircas_2022.pdf?v=1766594012');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('EL ENEMIGO', 'vino', 'tinto internacional', 'Malbec argentino del enólogo estrella de Catena (Alejandro Vigil). 93 Parker. Cabernet Franc aporta estructura única.', 'Aleanna', 'Mendoza', 'Argentina', '89% Malbec / 8% Cabernet franc / 3% Petit verdot', 'Violeta profundo con reflejos rubí.', 'Violetas, lavanda, fruta madura, grafito, vainilla y tostados.', 'Aterciopelada y carnosa, taninos cremosos; final mineral y largo.', 'Color violeta profundo con reflejos rubí. En nariz, violetas, lavanda, fruta roja y negra madura, grafito, tiza y un fondo especiado con vainilla y notas tostadas de crianza. Boca aterciopelada y carnosa, cuerpo medio, acidez fresca y equilibrada. Taninos redondos y cremosos, con un punto más estructurado que da el Cabernet Franc. Final largo, mineral y persistente.
Maridaje: asado argentino, entrecot a la parrilla, caza menor, venado, quesos curados.', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '16-17 °C', 14.0, NULL, 37.5, '{"potencia": 7, "acidez": 5, "taninos": 7, "dulzura": 2, "afrutado": 6}'::jsonb, '[{"critico": "Robert Parker", "nota": "93"}]'::jsonb, true, false, 620, 'Fermentación con levaduras indígenas, racimos enteros + uva despalillada según parcela. Uso parcial de raspón. 15 meses en fudres de roble.', 'Aleanna es proyecto de Alejandro Vigil (winemaker estrella de Catena Zapata) y su mujer Adrianna Catena. Fundada en 2007.', 'Vigil es uno de los enólogos más respetados de Argentina. "El Enemigo" es su proyecto personal — Malbec con Cabernet Franc, que aporta más estructura.', 'https://www.vinissimus.com/es/vino/el-enemigo-malbec/?srsltid=AfmBOorauG7zitKYmzFzOacX9iydIEAjDD0mo9gjp0A2W4brQI9NBcim');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('Domaine de l''aigle rou', 'vino', 'tinto internacional', '¡Pinot Noir en el Mediterráneo francés! Biodinámico Demeter, 93 Decanter. Sorprendente y elegante.', 'Gérard Bertrand.', 'Domaine de
l’Aigle', 'Languedoc Rosellón', 'Pinot noir', 'Rojo rubí con ligeros reflejos cobrizos.', 'Bayas pequeñas (frambuesa, grosella) con notas tostadas.', 'Tierna, afrutada y especiada; taninos sedosos, final largo.', 'Color rojo rubí con ligeros reflejos cobrizos.
Nariz: Muy intensa, dominada por aromas de bayas pequeñas (frambuesa, grosella) mezclados con notas tostadas.
Boca: Es un vino tierno, afrutado y finamente especiado. Destaca por sus taninos finos y sedosos, una estructura excepcional y un final largo y persistente sobre la fruta.', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '15-17 °C', 14.0, NULL, 40.5, '{"potencia": 5, "acidez": 6, "taninos": 4, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 630, 'Biodinámico (Demeter); 93 puntos Decanter; oro Bettane & Desseauve 2019 y 2020.', 'Gérard Bertrand es figura icónica del Languedoc. Compró Domaine de l''Aigle por su altitud (zona "fresca" del Languedoc).', 'Pinot Noir en el Mediterráneo francés — algo poco habitual; logra un perfil aromático sorprendente gracias a la altitud del viñedo. Biodinámica certificada Demeter.', 'https://www.gerard-bertrand.com/products/domaine-de-laigle-pinot-noir-2022-75cl?srsltid=AfmBOopPYqf3QsqkxEn0z9uR3N9PTlNxhP1DhRMZAukxnj8lfkaFkMLm#erid43459960');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('BEAUCASTEL Châteauneuf-du-Pape Rouge 2021', 'vino', 'tinto internacional', 'Familia Perrin desde 1909, referencia del Ródano. Hasta 13 variedades en su coupage. Potente y sedoso.', 'Château de Beaucastel', 'Châteauneuf-du-Pape AOC', 'Ródano (Francia)', 'Garnacha, Mourvèdre, Syrah, Cinsault y otras', 'Granate intenso con reflejos violáceos.', 'Fruta negra, especias, garrigue y cuero.', 'Potente y sedosa, taninos integrados; gran complejidad y largura.', 'Único Ródano premium · Nombre canónico · Apertura de categoría', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '17-18 °C', 14.0, NULL, 204.0, '{"potencia": 6, "acidez": 5, "taninos": 5, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 640, 'Largas crianzas; coupage de hasta 13 variedades.', 'Château de Beaucastel está en Courthézon (Vaucluse). En manos de la familia Perrin desde 1909 — referencia absoluta del Ródano.', 'Châteauneuf-du-Pape permite hasta 13 variedades en su coupage — Beaucastel las usa todas. El nombre viene de los papas que vivieron en Avignon en el siglo XIV.', 'https://beaucastel.com');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('ANTINORI Tignanello 2022', 'vino', 'tinto internacional', 'PIONERO Súper Toscano (1971). Antinori = 26 generaciones haciendo vino (desde 1385). Cambió la historia del vino italiano.', 'Marchesi Antinori', 'Toscana IGT', 'Toscana (Italia)', 'Sangiovese, Cabernet Sauvignon, Cab. Franc', 'Rubí intenso y profundo.', 'Cereza, ciruela, especias, tabaco y vainilla.', 'Estructurada y equilibrada; taninos pulidos, final largo.', 'Pionero de la categoría · Muy reconocible · Rotación alta', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '17-18 °C', 14.0, NULL, 250.0, '{"potencia": 7, "acidez": 5, "taninos": 7, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 650, 'Crianza larga en barrica francesa.', 'Marchesi Antinori, familia florentina de viticultores desde 1385 (¡640 años!). 26 generaciones haciendo vino.', 'Tignanello (1971) es uno de los PRIMEROS Súper Toscanos — vino que rompió las reglas del Chianti al añadir Cabernet Sauvignon. Cambió la historia del vino italiano.', 'https://antinori.it');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('TENUTA SAN GUIDO Sassicaia 2020', 'vino', 'tinto internacional', 'PADRE de los Súper Toscanos. La DOC Bolgheri se creó EN 1994 ESPECÍFICAMENTE PARA SASSICAIA.', 'Tenuta San Guido', 'Bolgheri DOC', 'Toscana (Italia)', 'Cabernet Sauvignon, Cab. Franc', 'Rubí intenso y brillante.', 'Fruta negra, grafito, especias y cedro.', 'Elegante, fina y profunda; taninos sedosos, final eterno.', 'Padre de la categoría · Ícono absoluto Italia', ARRAY['Carnes rojas','Caza','Quesos curados','Asados']::text[], '17-18 °C', 14.0, NULL, 558.0, '{"potencia": 7, "acidez": 5, "taninos": 7, "dulzura": 2, "afrutado": 6}'::jsonb, NULL, true, false, 660, '24 meses en barrica francesa.', 'Tenuta San Guido es de la familia Incisa della Rocchetta. Mario Incisa plantó Cabernet en Bolgheri en los 40 — una herejía que cambiaría todo.', 'PADRE de los Súper Toscanos. Primera cosecha comercializada: 1968 (sale 1971). Bolgheri DOC se creó EN 1994 ESPECÍFICAMENTE PARA SASSICAIA. Es el único vino italiano con su propia DOC.', 'https://sassicaia.com');

-- Dulces
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('MIQUEL GELABERT Dolç des Port', 'vino', 'dulce', 'Vino dulce mallorquín tradicional — SIN alcohol ni azúcar añadido. Perfecto con ensaimada y robiols.', 'Miquel Gelabert', 'VT Mallorca', 'Manacor (Pla i Llevant)', 'Syrah, Pinot Noir', 'Color brandy.', 'Piel de naranja confitada, avellanas tostadas, miel y especias.', 'Dulce, denso y aterciopelado; final muy especial.', 'Rojo granate · Fruta negra confitada, chocolate, especia · Dulce aterciopelado · 12-14 °C Vino dulce que envejece años en barrica. Denso y con cuerpo, sus aromas a pasas y a miel lo convierten en algo especial para acompañar la ensaimada, robiols y todo tipo de pastelería mallorquina.vino elaborado como se haría tradicionalmente en Mallorca, mezclando uvas blancas y tintas y evaporando el mosto hasta reducirlo a la mitad. No contiene alcohol ni azúcar añadido.
Su color es el de un buen brandy. Tiene aromas de piel de naranja confitada y de avellanas tostadas, y en la boca el alcohol no se encuentra por lo que no molesta. Es fresco y nada empalagoso.', ARRAY['Postres','Foie','Quesos azules']::text[], '12-14 °C', 12.0, 6.52, 39.0, '{"potencia": 6, "acidez": 6, "taninos": 1, "dulzura": 9, "afrutado": 8}'::jsonb, NULL, true, false, 670, 'Envejece años en barrica; mosto reducido a la mitad por evaporación.', 'Miquel Gelabert (Manacor) es bodega biodinámica histórica mallorquina. El Dolç des Port se elabora como tradicionalmente en Mallorca: evaporando el mosto.', 'NO contiene alcohol añadido NI azúcar añadido — el dulzor sale solo por evaporación natural. Es una receta mallorquina ancestral, casi extinta.', 'https://vinsmiquelgelabert.com/producto/dolc-des-morro-2018/');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('LUSTAU PX San Emilio', 'vino', 'dulce', 'PX nombrado MEJOR DEL MUNDO 2021 (IWC). 12 años en Jerez. Para postres y foie. ¡Sobre helado de vainilla, mágico!', 'Lustau', 'Jerez', 'Andalucía', 'Pedro Ximénez', 'Caoba muy oscuro con ribete yodado.', 'Pasas, higos, regaliz, café y aromas florales y cítricos.', 'Untuosa, muy dulce y larga; con elegante acidez.', 'Caoba intensa · Pasas, higos, regaliz, café · Muy dulce, untuoso, largo · 10-12 °C El vino de postre por excelencia. Envejecido durante 12 años en Jerez de la Frontera. Tras la vendimia, las uvas se “solean” en la viña para que se pasifiquen y concentren su azúcar natural. Elegido mejor Pedro Ximenez del 2021 en la International Wine Challenge.De color caoba muy oscuro con ribete yodado. Aromas florales y cítricos, con sabor a frutas pasas y especiadas. Pleno y muy largo en el paladar. Enormemente dulce, con una agradable acidez.Servir a 10 – 12ºC. Vino de postre en sí mismo, puede acompañar hojaldres, pastas y postres elaborados a base de frutas o yogur.', ARRAY['Postres','Foie','Quesos azules']::text[], '10-12 °C', 12.0, NULL, 44.0, '{"potencia": 6, "acidez": 6, "taninos": 1, "dulzura": 10, "afrutado": 8}'::jsonb, NULL, true, false, 680, '12 años en Jerez; uvas asoleadas en viña ("solearse").', 'Bodegas Lustau (Jerez de la Frontera, Cádiz) es referencia mundial del vino de Jerez. Llevan más de 125 años haciendo vinos con criaderas y soleras.', '¡Mejor PX del 2021 en la International Wine Challenge! Las uvas se "solean" — se exponen al sol al cosecharlas para que se pasifiquen, concentrando azúcar.', 'https://caballero.es/tienda/vinos/vinos-de-jerez/lustau-px-san-emilio/');
INSERT INTO carta_bebidas (nombre, categoria, subcategoria, descripcion, bodega, region, pais, uvas, nota_visual, nota_nariz, nota_boca, nota_cata, maridajes, temperatura, graduacion, precio_copa, precio_botella, caracteristicas, puntuaciones, disponible, destacado, orden, crianza, historia, curiosidad, web_oficial) VALUES ('TOKAJI OREMUS Aszú 5 Puttonyos', 'vino', 'dulce', 'El "rey de los vinos" (Luis XIV). Vega Sicilia opera Tokaj. Viñedos UNESCO. 95 Suckling.', 'Oremus', 'Tokaj', 'Hungría', 'Furmint, Hárslevelű', 'Dorado ámbar.', 'Albaricoque confitado, miel, botrytis y notas balsámicas.', 'Sabrosa, plena y glicérica; acidez sublime equilibra el dulzor.', 'Dorado ámbar · Albaricoque confitado, miel, botrytis · Dulce noble, acidez sublime · 10-12 °C vino dulce complejo con aromas de frutas exóticas, frutas blancas y frutas de hueso, notas de acacias y toques de miel y balsámicos. En boca es sabroso, pleno y glicérico. Muestra una acidez equilibrada que permite que no fácil de beber y no empalagoso. El final es largo y con deliciosos toques de tostados, pastelería y compota de manzana.', ARRAY['Postres','Foie','Quesos azules']::text[], '10-12 °C', 12.0, NULL, 104.0, '{"potencia": 6, "acidez": 8, "taninos": 1, "dulzura": 9, "afrutado": 8}'::jsonb, NULL, true, false, 690, 'Botritis (podredumbre noble); 5 puttonyos = nivel de dulzor 120-150 g/l. 95 Suckling.', 'Tokaj-Oremus es propiedad de TEMPOS VEGA SICILIA (familia Álvarez) desde 1993. Ribera del Duero opera la legendaria región húngara de Tokaj. Sus viñedos están catalogados como Patrimonio de la Humanidad por la UNESCO.', 'Tokaj es el vino dulce más antiguo del mundo (siglo XV). Luis XIV lo llamó "el rey de los vinos, el vino de los reyes". Botrytis = hongo noble que concentra el azúcar.', 'https://www.decantalo.com/es/es/tokaji-oremus-aszu-5-puttonyos.html?srsltid=AfmBOory8GfydJA8lD4yRBZNQ9thp7r2k98cZ2RB6uJUxmKM_ERdj5eZ');

-- Total: 69 vinos